    'как записаться байдарки',
    'безопасность походов Молдова'
  ],
  alternates: {
    canonical: '/faq', // Защита от дублей
  },
  openGraph: {
    title: 'Частые Вопросы | Турклуб «Эва»',
    description: 'Ответы на вопросы о турах: как записаться, что взять, цены, безопасность, подходит ли новичку.',
    url: 'https://evatur.club/faq',
    siteName: 'Турклуб «Эва»',
    type: 'website',
    locale: 'ru_RU',
  }
};

// 🤖 ЧИСТЫЕ ДАННЫЕ ДЛЯ РОБОТОВ GOOGLE (FAQPage Schema)
const faqSchemaData = [
  {
    question: "Как записаться и можно ли новичкам?",
    answer: "Запись осуществляется через сайт, Telegram-бота, гидов или соцсети. Новичкам — можно! 90% наших маршрутов разработаны так, чтобы их прошел человек без спецподготовки."
  },
  {
    question: "Оплата и условия отмены (Возврат)",
    answer: "Оплата возможна наличными, мобильным платежом (QR) или переводом. Если вы отменяете участие, предоплата возвращается только в случае, если найдена замена (вами или из листа ожидания)."
  },
  {
    question: "Здоровье, Аптечка и Лекарства",
    answer: "У гида всегда есть базовая групповая аптечка. Если у вас есть хронические заболевания или специфика организма — вы обязаны иметь при себе личные лекарства."
  },
  {
    question: "Алкоголь и Правила поведения",
    answer: "Во время активной части маршрута действует правило самоконтроля. Вечером умеренное потребление алкоголя возможно, если это не мешает отдыху других участников."
  },
  {
    question: "Что брать с собой и Погода",
    answer: "Перед каждым туром мы высылаем подробный чек-лист снаряжения. Маршрут может быть изменен гидом ради безопасности группы при плохих погодных условиях."
  },
  {
    question: "Можно ли с детьми?",
    answer: "Да, мы любим семейные выезды! Дети участвуют с родителями. Возможность участия ребенка зависит от сложности конкретного маршрута."
  }
];

export default function FAQLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  // Генерируем разметку
  const jsonLd = {
    '@context': 'https://schema.org',
    '@type': 'FAQPage',
    mainEntity: faqSchemaData.map((item) => ({
      '@type': 'Question',
      name: item.question,
      acceptedAnswer: {
        '@type': 'Answer',
        text: item.answer,
      },
    })),
  };

  return (
    <>
      {/* Скрытый скрипт, который Гугл превратит в красивые ответы в поиске */}
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }}
      />
      {/* Твой красивый клиентский компонент с аккордеоном */}
      {children}
    </>
  );
}

