"use client";

// src/components/SectionErrorBoundary.tsx
//
// Переиспользуемый ErrorBoundary для секций главной страницы.
// Если секция падает с JS ошибкой — показывает тихий fallback
// вместо белого экрана на всю страницу.
//
// Использование:
//   <SectionErrorBoundary label="ToursBrowser">
//     <ToursBrowserWrapper />
//   </SectionErrorBoundary>

import { ErrorBoundary } from "react-error-boundary";
import type { ReactNode } from "react";

interface Props {
  children: ReactNode;
  // label используется в console.error для быстрой диагностики
  label?: string;
  // Минимальная высота fallback-плашки, чтобы не ломать layout
  minHeight?: string;
}

function SectionFallback({
  label,
  minHeight,
  resetErrorBoundary,
}: {
  label?: string;
  minHeight?: string;
  resetErrorBoundary: () => void;
}) {
  return (
    <section
      className="flex flex-col items-center justify-center gap-4 py-16 px-4 bg-slate-950 border-y border-white/5"
      style={{ minHeight: minHeight ?? "200px" }}
      aria-label={label ? `Ошибка секции: ${label}` : "Ошибка секции"}
    >
      <p className="text-slate-300 text-sm font-medium text-center max-w-xs">
        Эта секция временно недоступна. Попробуйте обновить страницу.
      </p>
      <button
        onClick={resetErrorBoundary}
        className="px-5 py-2 rounded-xl bg-white/5 border border-white/10 text-white text-xs font-bold uppercase tracking-wider hover:bg-teal-500 hover:border-teal-500 transition-colors"
      >
        Попробовать снова
      </button>
    </section>
  );
}

export default function SectionErrorBoundary({
  children,
  label,
  minHeight,
}: Props) {
  return (
    <ErrorBoundary
      fallbackRender={({ resetErrorBoundary }) => (
        <SectionFallback
          label={label}
          minHeight={minHeight}
          resetErrorBoundary={resetErrorBoundary}
        />
      )}
      onError={(error) => {
        // В продакшене сюда можно подключить Sentry/LogRocket
        console.error(`[ErrorBoundary${label ? ` | ${label}` : ""}]`, error);
      }}
    >
      {children}
    </ErrorBoundary>
  );
}

'use server';

import { prisma } from '@/lib/prisma';
import { createServerSupabaseClient } from '@/lib/supabase/server';
import { revalidatePath } from 'next/cache';
import { getLevelName } from '@/lib/constants/levels'; // ✅ ПОДКЛЮЧИЛИ ИСТОЧНИК ПРАВДЫ

export async function saveOnboardingDataAction(phoneRaw: string, name: string) {
  const supabase = await createServerSupabaseClient();
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) return { success: false, error: 'Не авторизован' };

  const phone = phoneRaw.replace(/[^\d+]/g, '');
  
  if (phone.length < 10) {
    return { success: false, error: 'Введен некорректный номер телефона' };
  }

  if (!name || name.trim().length < 2) {
    return { success: false, error: 'Пожалуйста, введите ваше реальное имя' };
  }

  try {
    const existing = await prisma.memberProfile.findUnique({ where: { phone } });
    if (existing && existing.userId !== user.id) {
      return { success: false, error: 'Этот номер уже привязан к другому аккаунту' };
    }

    const profile = await prisma.memberProfile.update({
      where: { userId: user.id },
      data: { 
        phone,
        name: name.trim() 
      }
    });

    const linkedBookings = await prisma.booking.updateMany({
      where: { 
        phone: phone, 
        memberId: null 
      },
      data: { memberId: profile.id },
    });

    await prisma.waitlist.updateMany({
      where: { 
        phone: phone, 
        memberId: null 
      },
      data: { memberId: profile.id },
    });

    if (linkedBookings.count > 0) {
      const stats = await prisma.booking.aggregate({
        where: { memberId: profile.id, status: { not: 'cancelled' } },
        _count: { id: true },
      });

      const bookingsWithTours = await prisma.booking.findMany({
        where: { memberId: profile.id, status: { not: 'cancelled' } },
        include: { tour: { select: { distance: true } } },
      });

      const totalKm = bookingsWithTours.reduce((sum, b) => {
        const km = parseFloat(b.tour?.distance ?? '0');
        return sum + (isNaN(km) ? 0 : km);
      }, 0);

      const tourCount = stats._count.id;
      await prisma.memberProfile.update({
        where: { id: profile.id },
        data: { 
          totalTours: tourCount, 
          totalKm, 
          level: getLevelName(tourCount) // ✅ ИСПОЛЬЗУЕМ ФУНКЦИЮ ИЗ КОНФИГА
        },
      });
    }

    revalidatePath('/account', 'layout'); 
    return { success: true, linkedCount: linkedBookings.count };
    
  } catch (error) {
    console.error('Onboarding Action Error:', error);
    return { success: false, error: 'Произошла ошибка при сохранении данных' };
  }
}

