"use client";

import React, { useState, useMemo } from 'react';
import { 
  Search, CheckCircle, Clock, Archive, Trash2, 
  MessageSquare, User, Tent, Briefcase, FileText, Heart, Star, Eye
} from 'lucide-react';
import { Inquiry, InquiryStatus, InquiryType } from '@prisma/client';
import { updateInquiryStatusAction, deleteInquiryAction } from '@/features/admin/actions/inquiries';
import { useToast } from '@/shared/context/ToastContext';

// Иконки для типов
const TYPE_ICONS = {
  TOUR: <Tent size={14} className="text-teal-500"/>,
  HR: <User size={14} className="text-purple-500"/>,
  BLOG: <FileText size={14} className="text-amber-500"/>,
  B2B: <Briefcase size={14} className="text-blue-500"/>,
  REVIEW: <Star size={14} className="text-yellow-400"/>,
  HELP: <Heart size={14} className="text-rose-500"/>,
};

// Лейблы для статусов
const STATUS_LABELS = {
  NEW: { label: 'Новое', color: 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20' },
  WORK: { label: 'В работе', color: 'bg-blue-500/10 text-blue-500 border-blue-500/20' },
  DONE: { label: 'Архив', color: 'bg-slate-500/10 text-slate-300 border-slate-500/20' },
};

interface Props {
  inquiries: Inquiry[];
}

export default function InquiriesTab({ inquiries: initialData }: Props) {
  const [inquiries, setInquiries] = useState(initialData);
  const [filterType, setFilterType] = useState<InquiryType | 'ALL'>('ALL');
  const [filterStatus, setFilterStatus] = useState<InquiryStatus | 'ALL'>('ALL');
  const { showToast } = useToast();

  // Фильтрация
  const filtered = useMemo(() => {
    return inquiries.filter(item => {
      const matchType = filterType === 'ALL' || item.type === filterType;
      const matchStatus = filterStatus === 'ALL' || item.status === filterStatus;
      return matchType && matchStatus;
    });
  }, [inquiries, filterType, filterStatus]);

  // Обработчики
  const handleStatus = async (id: string, newStatus: InquiryStatus) => {
    // Оптимистичное обновление UI
    setInquiries(prev => prev.map(i => i.id === id ? { ...i, status: newStatus } : i));
    const res = await updateInquiryStatusAction(id, newStatus);
    if (!res.success) showToast('Ошибка обновления', 'error');
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Удалить навсегда?')) return;
    setInquiries(prev => prev.filter(i => i.id !== id));
    await deleteInquiryAction(id);
    showToast('Удалено', 'success');
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between gap-4 md:items-center">
         <h1 className="text-2xl font-black uppercase tracking-tight dark:text-white flex items-center gap-3">
            <MessageSquare className="text-teal-500"/> Обращения
            <span className="text-sm bg-slate-100 dark:bg-slate-800 text-slate-300 px-2 py-1 rounded-lg">
                {inquiries.filter(i => i.status === 'NEW').length} новых
            </span>
         </h1>

         {/* Фильтры */}
         <div className="flex gap-2 overflow-x-auto pb-1">
             {/* Фильтр Статуса */}
             <div className="flex bg-white dark:bg-slate-900 p-1 rounded-xl border border-slate-200 dark:border-slate-800">
                 {(['ALL', 'NEW', 'WORK', 'DONE'] as const).map(s => (
                    <button 
                       key={s} onClick={() => setFilterStatus(s)}
                       className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-colors ${filterStatus === s ? 'bg-slate-100 dark:bg-slate-800 text-slate-900 dark:text-white' : 'text-slate-300 hover:text-slate-600'}`}
                    >
                        {s === 'ALL' ? 'Все' : s === 'NEW' ? 'Новые' : s === 'WORK' ? 'В работе' : 'Архив'}
                    </button>
                 ))}
             </div>
         </div>
      </div>

      {/* Список карточек (Mobile-first адаптация вместо таблицы) */}
      <div className="grid gap-3">
         {filtered.length === 0 && (
             <div className="text-center py-20 text-slate-300">Нет обращений по выбранным фильтрам</div>
         )}
         
         {filtered.map(item => {
             const payload = item.payload as any || {};
             
             return (
               <div key={item.id} className={`group relative bg-white dark:bg-slate-900 p-5 rounded-2xl border transition-all ${item.status === 'NEW' ? 'border-teal-500/40 shadow-sm' : 'border-slate-200 dark:border-slate-800 opacity-80 hover:opacity-100'}`}>
                  
                  {/* Верхняя строка: Тип + Дата + Статус */}
                  <div className="flex justify-between items-start mb-3">
                      <div className="flex items-center gap-2">
                          <div className="p-2 bg-slate-50 dark:bg-slate-800 rounded-lg border border-slate-100 dark:border-slate-700">
                             {TYPE_ICONS[item.type]}
                          </div>
                          <div>
                              <span className="text-[12px] font-bold text-slate-300 block uppercase tracking-wider">{item.type}</span>
                              <span className="text-xs text-slate-300 font-mono">
                                  {new Date(item.createdAt).toLocaleString('ru-RU')}
                              </span>
                          </div>
                      </div>
                      
                      {/* Свитчер статуса */}
                      <div className="flex items-center gap-1 bg-slate-50 dark:bg-slate-800 p-1 rounded-lg">
                          <button onClick={() => handleStatus(item.id, 'NEW')} title="Новое" className={`p-1.5 rounded ${item.status === 'NEW' ? 'bg-emerald-500 text-white shadow-sm' : 'text-slate-300 hover:bg-slate-200'}`}><Clock size={14}/></button>
                          <button onClick={() => handleStatus(item.id, 'WORK')} title="В работе" className={`p-1.5 rounded ${item.status === 'WORK' ? 'bg-blue-500 text-white shadow-sm' : 'text-slate-300 hover:bg-slate-200'}`}><Eye size={14}/></button>
                          <button onClick={() => handleStatus(item.id, 'DONE')} title="Архив" className={`p-1.5 rounded ${item.status === 'DONE' ? 'bg-slate-500 text-white shadow-sm' : 'text-slate-300 hover:bg-slate-200'}`}><Archive size={14}/></button>
                      </div>
                  </div>

                  {/* Контент */}
                  <div className="grid md:grid-cols-4 gap-4 items-start">
                      {/* 1. Кто */}
                      <div className="md:col-span-1">
                          <h4 className="font-bold text-slate-900 dark:text-white">{item.name}</h4>
                          <div className="text-sm text-teal-600 font-medium mt-1">
                              {item.phone && <div className="flex items-center gap-1">{item.phone}</div>}
                              {item.social && <div className="flex items-center gap-1">@{item.social.replace('@','')}</div>}
                          </div>
                      </div>

                      {/* 2. Суть */}
                      <div className="md:col-span-2">
                          {/* Специфичные поля */}
                          {payload.tour && <div className="mb-2 text-xs font-bold text-purple-500 bg-purple-500/10 px-2 py-1 rounded w-fit">Тур: {payload.tour}</div>}
                          {payload.role && <div className="mb-2 text-xs font-bold text-indigo-500 bg-indigo-500/10 px-2 py-1 rounded w-fit">Роль: {payload.role}</div>}
                          {payload.company && <div className="mb-2 text-xs font-bold text-blue-500 bg-blue-500/10 px-2 py-1 rounded w-fit">Компания: {payload.company}</div>}
                          {payload.rating && <div className="mb-2 text-xs font-bold text-amber-500 bg-amber-500/10 px-2 py-1 rounded w-fit">Оценка: {payload.rating} ★</div>}
                          
                          <p className="text-sm text-slate-600 dark:text-slate-300 whitespace-pre-wrap leading-relaxed">
                              {item.message}
                          </p>
                      </div>

                      {/* 3. Действия */}
                      <div className="md:col-span-1 flex md:justify-end items-start pt-1">
                          <button 
                            onClick={() => handleDelete(item.id)}
                            className="flex items-center gap-2 px-3 py-2 text-xs font-bold text-rose-500 hover:bg-rose-50 rounded-lg transition-colors border border-transparent hover:border-rose-100"
                          >
                             <Trash2 size={14}/> Удалить
                          </button>
                      </div>
                  </div>
                  
                  {/* Подсветка "Новое" */}
                  {item.status === 'NEW' && (
                      <span className="absolute -left-px top-8 bottom-8 w-1 bg-teal-500 rounded-r-full"/>
                  )}
               </div>
             )
         })}
      </div>
    </div>
  );
}

files.src/features/admin/components/views/Revi:
import React from 'react';
import { Plus, MessageCircle, Send, Phone, Instagram, Edit, Trash2, Tags, CheckCircle2, Circle } from 'lucide-react';
import Button from '@/shared/ui/Button';
import { Review } from '@prisma/client';

interface ReviewsTabProps {
  reviews: Review[];
  onAdd: () => void;
  onEdit: (review: Review) => void;
  onDelete: (id: string) => void;
  onToggleStatus: (review: Review) => void;
}

// Конфиг для бейджей категорий
const CATEGORY_MAP: Record<string, { label: string, colorClass: string }> = {
  general: { label: 'Местное', colorClass: 'bg-slate-100 text-slate-600 border-slate-200 dark:bg-slate-800 dark:text-slate-300 dark:border-slate-700' },
  kayak: { label: 'Сплавы', colorClass: 'bg-blue-50 text-blue-600 border-blue-200 dark:bg-blue-500/10 dark:text-blue-400 dark:border-blue-500/20' },
  sup: { label: 'SUP-туры', colorClass: 'bg-teal-50 text-teal-600 border-teal-200 dark:bg-teal-500/10 dark:text-teal-400 dark:border-teal-500/20' },
  mountains: { label: 'Туры в горы', colorClass: 'bg-emerald-50 text-emerald-600 border-emerald-200 dark:bg-emerald-500/10 dark:text-emerald-400 dark:border-emerald-500/20' },
  kids: { label: 'Детские', colorClass: 'bg-orange-50 text-orange-600 border-orange-200 dark:bg-orange-500/10 dark:text-orange-400 dark:border-orange-500/20' },
};

export default function ReviewsTab({ reviews, onAdd, onEdit, onDelete, onToggleStatus }: ReviewsTabProps) {
  
  // Хелпер для иконки источника
  const getSourceIcon = (source: string) => {
    switch (source) {
      case 'tg': return <Send size={14} className="text-sky-500"/>;
      case 'viber': return <Phone size={14} className="text-purple-500"/>;
      case 'instagram': return <Instagram size={14} className="text-pink-500"/>;
      default: return <MessageCircle size={14} className="text-teal-500" />;
    }
  };

  return (
    <div className="space-y-6">
      {/* Шапка */}
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-black uppercase dark:text-white">Отзывы</h2>
        <Button variant="primary" onClick={onAdd} className="bg-teal-600 hover:bg-teal-700">
          <Plus size={18} className="mr-2"/> Добавить
        </Button>
      </div>

      {/* --- ДЕСКТОПНАЯ ТАБЛИЦА --- */}
      <div className="hidden md:block bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 overflow-hidden shadow-sm">
        <table className="w-full text-sm text-left">
          <thead className="bg-slate-50 dark:bg-slate-800/50 text-slate-300 font-black uppercase text-[12px] tracking-widest">
            <tr>
              <th className="p-5">Клиент</th>
              <th className="p-5">Источник</th>
              <th className="p-5">Направление</th>
              <th className="p-5 w-2/5">Текст</th>
              <th className="p-5 text-center">Статус</th>
              <th className="p-5 text-right">Действия</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
            {reviews.map(review => {
              // Если категория не задана или старая, подставляем дефолтную
              const catConfig = CATEGORY_MAP[review.category] || CATEGORY_MAP.general;

              return (
                // Класс group тут критически важен для появления кнопок действий при наведении
                <tr key={review.id} className="group hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-colors duration-200">
                  <td className="p-5 font-bold text-slate-800 dark:text-white">
                    <div className="flex items-center gap-3">
                        <div className="w-8 h-8 rounded-full bg-slate-200 dark:bg-slate-800 flex items-center justify-center text-xs font-black text-slate-300 shrink-0 uppercase">
                            {review.name[0]}
                        </div>
                        <span className="truncate max-w-[120px]">{review.name}</span>
                    </div>
                  </td>
                  <td className="p-5">
                    <div className="flex items-center gap-2 border border-slate-200 dark:border-slate-700 rounded-lg px-2.5 py-1 w-fit bg-slate-50 dark:bg-slate-800/50">
                      {getSourceIcon(review.source)} 
                      <span className="text-[12px] font-bold uppercase text-slate-300">{review.source}</span>
                    </div>
                  </td>
                  <td className="p-5">
                    <div className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg border text-[12px] font-bold uppercase tracking-wider ${catConfig.colorClass}`}>
                       <Tags size={12} strokeWidth={2.5} />
                       {catConfig.label}
                    </div>
                  </td>
                  <td className="p-5 text-slate-600 dark:text-slate-300 whitespace-pre-wrap leading-relaxed text-xs">
                    <div className="line-clamp-2" title={review.text}>{review.text}</div>
                  </td>
                  <td className="p-5 text-center">
                    {/* Кастомный переключатель статуса */}
                    <button 
                      onClick={() => onToggleStatus(review)}
                      className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[12px] font-bold uppercase transition-all ${
                        review.isActive 
                        ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-500/10 dark:text-emerald-400 hover:bg-emerald-200 dark:hover:bg-emerald-500/20' 
                        : 'bg-slate-100 text-slate-300 dark:bg-slate-800 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700'
                      }`}
                    >
                      {review.isActive ? <CheckCircle2 size={12}/> : <Circle size={12}/>}
                      {review.isActive ? 'Виден' : 'Скрыт'}
                    </button>
                  </td>
                  <td className="p-5 text-right">
                    {/* Кнопки появляются при наведении на строку */}
                    <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                      <button onClick={() => onEdit(review)} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg text-slate-300 hover:text-teal-500 transition-colors">
                        <Edit size={16}/>
                      </button>
                      <button onClick={() => onDelete(review.id)} className="p-2 hover:bg-red-50 dark:hover:bg-red-500/10 rounded-lg text-slate-300 hover:text-red-500 transition-colors">
                        <Trash2 size={16}/>
                      </button>
                    </div>
                  </td>
                </tr>
              )
            })}
          </tbody>
        </table>
      </div>

      {/* --- МОБИЛЬНЫЕ КАРТОЧКИ --- */}
      <div className="md:hidden space-y-4">
        {reviews.map(review => {
           const catConfig = CATEGORY_MAP[review.category] || CATEGORY_MAP.general;
           return (
            <div key={review.id} className="bg-white dark:bg-slate-900 p-4 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm relative flex flex-col">
                <div className="flex justify-between items-start mb-4">
                  <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center font-black text-slate-300 uppercase shrink-0">
                          {review.name[0]}
                      </div>
                      <div>
                          <h4 className="font-bold text-slate-900 dark:text-white text-sm">{review.name}</h4>
                          <div className="flex items-center gap-2 mt-1">
                              <span className="flex items-center gap-1 text-[9px] text-slate-300 uppercase font-bold">
                                  {getSourceIcon(review.source)} {review.source}
                              </span>
                              {/* Бейдж категории на мобилке без иконки для экономии места */}
                              <span className={`text-[9px] font-bold uppercase tracking-wider px-1.5 py-0.5 rounded border ${catConfig.colorClass}`}>
                                  {catConfig.label}
                              </span>
                          </div>
                      </div>
                  </div>
                  <button onClick={() => onToggleStatus(review)} className={`p-1 transition-colors ${review.isActive ? 'text-emerald-500' : 'text-slate-300 dark:text-slate-600'}`}>
                    {review.isActive ? <CheckCircle2 size={20}/> : <Circle size={20}/>}
                  </button>
                </div>
                
                <p className="text-sm text-slate-600 dark:text-slate-300 mb-4 bg-slate-50 dark:bg-slate-800/50 p-3.5 rounded-xl italic leading-relaxed">
                    "{review.text}"
                </p>
                
                <div className="flex justify-end gap-2 border-t border-slate-100 dark:border-slate-800 pt-3">
                    <button onClick={() => onEdit(review)} className="px-4 py-2 bg-slate-100 dark:bg-slate-800 rounded-xl text-slate-300 dark:text-slate-300 text-xs font-bold flex items-center gap-2 active:scale-95 transition-transform">
                        <Edit size={14}/> Править
                    </button>
                    <button onClick={() => onDelete(review.id)} className="px-4 py-2 bg-red-50 dark:bg-red-500/10 text-red-500 rounded-xl text-xs font-bold flex items-center gap-2 active:scale-95 transition-transform">
                        <Trash2 size={14}/> Удалить
                    </button>
                </div>
            </div>
          )
        })}
      </div>
    </div>
  );
}

