export default async function ToursBrowserWrapper({ 
  limit = 8, 
  title, 
  subtitle 
}: ToursBrowserWrapperProps) {
  
  // 1. Запрашиваем туры и категории параллельно
  const [tours, tCatRes] = await Promise.all([
