"use client";

import React, { useState, useEffect } from 'react';
import { AlignJustify, ArrowUp } from 'lucide-react';
import { clsx } from 'clsx';

export default function TourStickyNav() {
  const [isVisible, setIsVisible] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsVisible(window.scrollY > 100);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollToSection = (id: string) => {
    const element = document.getElementById(id);
    if (element) {
      const y = element.getBoundingClientRect().top + window.scrollY - 80;
      window.scrollTo({ top: y, behavior: 'smooth' });
    }
    setMobileMenuOpen(false);
  };

  const scrollToTop = () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const navItems = [
    { id: 'about',   label: 'Описание' },
    { id: 'program', label: 'Программа' },
    { id: 'gallery', label: 'Фото' },
    { id: 'dates',   label: 'Даты' },
    { id: 'faq',     label: 'FAQ' },
  ];

  return (
    <header
      className={clsx(
        // ✅ transition-transform — composited, панель скользит без Layout recalc
        "fixed top-0 left-0 right-0 z-[100] bg-slate-900/95 backdrop-blur-md border-b border-white/10 transition-transform duration-300 ease-in-out shadow-2xl",
        isVisible ? "translate-y-0" : "-translate-y-full"
      )}
    >
      <div className="container mx-auto px-4 h-16 flex items-center justify-between">

        <button
          onClick={scrollToTop}
          aria-label="Прокрутить наверх"
          // ✅ transition-colors вместо transition-all — только цвет, без layout
          className="flex items-center gap-2 text-white font-bold uppercase hover:text-teal-400 transition-colors"
        >
          <div className="w-8 h-8 rounded-full bg-white/10 flex items-center justify-center">
            <ArrowUp size={16} aria-hidden="true" />
          </div>
          <span className="hidden md:inline text-xs tracking-widest">Наверх</span>
        </button>

        <nav className="hidden md:flex items-center gap-8" aria-label="Навигация по разделам тура">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => scrollToSection(item.id)}
              // ✅ transition-colors вместо transition-all
              className="text-xs font-bold text-slate-300 hover:text-teal-400 hover:bg-white/5 px-3 py-2 rounded-lg transition-colors uppercase tracking-wide"
            >
              {item.label}
            </button>
          ))}
        </nav>

        <button
          className="md:hidden text-white p-2"
          aria-label="Открыть меню навигации"
          aria-expanded={mobileMenuOpen}
          aria-controls="mobile-tour-nav"
          onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
        >
          <AlignJustify aria-hidden="true" />
        </button>

      </div>

      {mobileMenuOpen && (
        <nav
          id="mobile-tour-nav"
          className="md:hidden border-t border-white/10 bg-slate-900/98"
          aria-label="Навигация по разделам тура (мобильная)"
        >
          <div className="container mx-auto px-4 py-3 flex flex-col gap-1">
            {navItems.map((item) => (
              <button
                key={item.id}
                onClick={() => scrollToSection(item.id)}
                // ✅ transition-colors вместо transition-all
                className="text-sm font-bold text-slate-300 hover:text-teal-400 hover:bg-white/5 px-3 py-3 rounded-lg transition-colors uppercase tracking-wide text-left"
              >
                {item.label}
              </button>
            ))}
          </div>
        </nav>
      )}
    </header>
  );
}

