      <link rel="preconnect" href="https://nglywosdwqxxctybwjeb.supabase.co" />
      <link rel="dns-prefetch" href="https://nglywosdwqxxctybwjeb.supabase.co" />
      {firstPostImage && (
        <link
          rel="preload"
          as="image"
          href={`${firstPostImage.split('?')[0]}?width=828&quality=65&format=origin`}
          fetchPriority="high"
        />
