                    <div className="text-slate-300 text-xs">{HOUSE.location.distanceCity} · {HOUSE.location.distanceMin}</div>
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-2">
                  <a
                    href={HOUSE.location.googleMaps}
                    target="_blank"
                    rel="noreferrer"
