"use client";

import React, { useState } from 'react';
import { Share2, Printer, MessageCircle, MousePointerClick, Check } from 'lucide-react';
import { Tour } from '@/features/tours/types';
import { useModalStore } from '@/shared/store/useModalStore';

interface TourActionButtonsProps {
  tour: Tour;
}

export default function TourActionButtons({ tour }: TourActionButtonsProps) {
  const [isCopied, setIsCopied] = useState(false);
  const openContactModal = useModalStore((state) => state.openContactModal);

  const handleShare = async () => {
    const shareData = {
      title: tour.title,
      text: `Посмотри этот тур: ${tour.title}`,
      url: window.location.href,
    };
    if (navigator.share) {
      try {
        await navigator.share(shareData);
      } catch (err) {
        console.error('Error sharing:', err);
      }
    } else {
      navigator.clipboard.writeText(window.location.href);
      setIsCopied(true);
      setTimeout(() => setIsCopied(false), 2000);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  return (
    <section className="scroll-mt-24 mb-12 print:hidden" id="actions">

      <div className="flex items-center gap-4 mb-6 md:mb-8">
        <div className="w-10 h-10 bg-teal-500/10 rounded-xl flex items-center justify-center text-teal-500 border border-teal-500/20">
          <MousePointerClick size={20} aria-hidden="true" />
        </div>
        <h2 className="text-2xl md:text-3xl font-black text-white uppercase">
          Другие действия
        </h2>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">

        {/* ПОДЕЛИТЬСЯ */}
        <button
          onClick={handleShare}
          aria-label={isCopied ? 'Ссылка скопирована' : 'Поделиться туром'}
          // ✅ transition-[border-color,background-color] вместо transition-all
          className="group relative flex items-center gap-4 p-5 bg-slate-900 border border-white/5 hover:border-teal-500/30 rounded-2xl transition-[border-color,background-color] hover:bg-slate-800 text-left"
        >
          {/* ✅ transition-transform на иконке — composited */}
          <div className="w-10 h-10 rounded-full bg-indigo-500/10 flex items-center justify-center text-indigo-400 group-hover:scale-110 transition-transform shrink-0">
            {isCopied ? <Check size={20} aria-hidden="true" /> : <Share2 size={20} aria-hidden="true" />}
          </div>
          <div>
            <span className="block text-[12px] uppercase font-bold text-slate-300 tracking-widest mb-0.5">
              {isCopied ? 'Ссылка скопирована' : 'Позвать друзей'}
            </span>
            <span className="block text-white font-bold text-sm">
              Поделиться туром
            </span>
          </div>
        </button>

        {/* PDF / ПЕЧАТЬ */}
        <button
          onClick={handlePrint}
          aria-label="Распечатать или сохранить тур как PDF"
          // ✅ transition-[border-color,background-color]
          className="group flex items-center gap-4 p-5 bg-slate-900 border border-white/5 hover:border-teal-500/30 rounded-2xl transition-[border-color,background-color] hover:bg-slate-800 text-left"
        >
          <div className="w-10 h-10 rounded-full bg-teal-500/10 flex items-center justify-center text-teal-500 group-hover:scale-110 transition-transform shrink-0">
            <Printer size={20} aria-hidden="true" />
          </div>
          <div>
            <span className="block text-[12px] uppercase font-bold text-slate-300 tracking-widest mb-0.5">
              Документ
            </span>
            <span className="block text-white font-bold text-sm">
              Версия для печати / PDF
            </span>
          </div>
        </button>

        {/* ВОПРОСЫ */}
        <button
          onClick={() => openContactModal(tour.title, 'TOUR')}
          aria-label="Написать нам вопрос по туру"
          // ✅ transition-[border-color,background-color]
          className="group flex items-center gap-4 p-5 bg-slate-900 border border-white/5 hover:border-teal-500/30 rounded-2xl transition-[border-color,background-color] hover:bg-slate-800 text-left"
        >
          <div className="w-10 h-10 rounded-full bg-emerald-500/10 flex items-center justify-center text-emerald-500 group-hover:scale-110 transition-transform shrink-0">
            <MessageCircle size={20} aria-hidden="true" />
          </div>
          <div>
            <span className="block text-[12px] uppercase font-bold text-slate-300 tracking-widest mb-0.5">
              Есть вопросы по туру?
            </span>
            <span className="block text-white font-bold text-sm">
              Напишите нам
            </span>
          </div>
        </button>

      </div>
    </section>
  );
}

"use client";

import React, { useEffect, useState } from 'react';
import { Tour } from '@/features/tours/types';
import { clsx } from 'clsx';
import { Info, X } from 'lucide-react';
import { useModalStore } from '@/shared/store/useModalStore';

interface TourBottomActionsProps {
  tour: Tour;
}

export default function TourBottomActions({ tour }: TourBottomActionsProps) {
  const [isVisible, setIsVisible] = useState(false);
  const [showHint, setShowHint] = useState(false);
  
  const openBookingModal = useModalStore((state) => state.openBookingModal);

  useEffect(() => {
    const handleScroll = () => {
      setIsVisible(window.scrollY > window.innerHeight * 0.8);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  if (!tour) return null;

  const prices = [
    { label: 'Взрослый',  value: tour.price },
    { label: 'Клубная',   value: tour.priceMember },
    { label: 'Детский',   value: tour.priceChild },
    { label: 'Семейный',  value: tour.priceFamily },
  ].filter((p) => typeof p.value === 'number' && p.value > 0);

  const minPrice = Math.min(...prices.map(p => p.value as number));
  const hasMultiplePrices = prices.length > 1;
  const isSoldOut = (tour.spotsLeft || 0) <= 0;

  return (
    <>
      {/* Оверлей для закрытия тултипа */}
      {showHint && (
        <div
          className="fixed inset-0 z-[55]"
          onClick={() => setShowHint(false)}
          aria-hidden="true"
        />
      )}

      <div
        className={clsx(
          "fixed bottom-0 left-0 right-0 z-[60] p-4 bg-slate-900/95 backdrop-blur-xl border-t border-white/10 transition-transform duration-300 lg:hidden pb-6 md:pb-6 safe-area-padding",
          isVisible ? "translate-y-0" : "translate-y-full"
        )}
        aria-label="Панель бронирования тура"
      >
        
        {/* Тултип со всеми тарифами */}
        <div
          role="tooltip"
          id="prices-tooltip"
          className={clsx(
            // ✅ ИСПРАВЛЕНИЕ: transition-[opacity,transform] вместо transition-all
            "absolute bottom-full left-4 mb-3 w-64 bg-slate-800 border border-white/10 rounded-2xl shadow-2xl overflow-hidden transition-[opacity,transform] origin-bottom-left",
            showHint ? "opacity-100 scale-100" : "opacity-0 scale-90 pointer-events-none"
          )}
        >
          <div className="bg-slate-950/50 p-3 border-b border-white/5 flex justify-between items-center">
            <span className="text-[12px] font-bold uppercase text-slate-300 tracking-wider">Все тарифы</span>
            {/* Кнопка закрытия тултипа — aria-label обязателен, т.к. только иконка */}
            <button
              onClick={() => setShowHint(false)}
              aria-label="Закрыть список тарифов"
            >
              <X size={14} className="text-slate-300 hover:text-white transition-colors" aria-hidden="true" />
            </button>
          </div>
          
          <div className="p-3 space-y-2">
            {prices.map((p, idx) => (
              <div key={idx} className="flex justify-between text-sm">
                <span className="text-slate-300">{p.label}</span>
                <span className="font-bold text-white">{(p.value as number).toLocaleString()} {tour.currency}</span>
              </div>
            ))}
          </div>
          
          <div className="absolute -bottom-1.5 left-6 w-3 h-3 bg-slate-800 rotate-45 border-r border-b border-white/10" aria-hidden="true" />
        </div>

        {/* Основной контент бара */}
        <div className="flex items-center gap-4">
          
          <div className="flex-grow">
            <p className="text-[12px] text-slate-300 uppercase font-bold tracking-wider mb-0.5">Стоимость участия</p>
            <div className="flex items-center gap-2">
              <div className="flex items-baseline gap-1">
                {hasMultiplePrices && <span className="text-sm text-slate-300 font-medium">от</span>}
                <span className="text-2xl font-black text-white">{minPrice.toLocaleString()}</span>
                <span className="text-xs font-bold text-teal-500">{tour.currency || 'RUB'}</span>
              </div>
              
              {/* Кнопка Info — aria-label + aria-expanded + aria-controls */}
              {hasMultiplePrices && (
                <button
                  onClick={() => setShowHint(!showHint)}
                  aria-label="Показать все тарифы"
                  aria-expanded={showHint}
                  aria-controls="prices-tooltip"
                  className={clsx(
                    "w-6 h-6 rounded-full flex items-center justify-center border transition-colors",
                    showHint
                      ? "bg-teal-500 text-slate-900 border-teal-500"
                      : "bg-white/5 text-slate-300 border-white/10 hover:bg-white/10"
                  )}
                >
                  <Info size={14} aria-hidden="true" />
                </button>
              )}
            </div>
          </div>
          
          <button
            onClick={() => openBookingModal(tour)}
            disabled={isSoldOut}
            aria-label={isSoldOut ? 'Мест нет' : `Записаться в тур ${tour.title}`}
            className={clsx(
              // ✅ ИСПРАВЛЕНИЕ: transition вместо transition-all
              "px-6 py-3 rounded-xl font-black uppercase tracking-wider text-sm shadow-lg active:scale-95 transition whitespace-nowrap",
              isSoldOut
                ? "bg-slate-800 text-slate-300 cursor-not-allowed"
                : "bg-teal-500 text-slate-900 shadow-teal-500/20"
            )}
          >
            {isSoldOut ? 'Мест нет' : 'Записаться'}
          </button>
          
        </div>
      </div>
    </>
  );
}

