@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    /* --- ДИЗАЙН СИСТЕМА 2026 --- */
    --background: 210 40% 98%; /* slate-50 */
    --foreground: 222.2 84% 4.9%; /* slate-950 */
    
    --card: 0 0% 100%;
    --card-foreground: 222.2 84% 4.9%;
 
    --popover: 0 0% 100%;
    --popover-foreground: 222.2 84% 4.9%;
 
    --primary: 173 80% 40%; /* teal-500 */
    --primary-foreground: 210 40% 98%;
 
