    --secondary-foreground: 222.2 47.4% 11.2%;
 
    --muted: 210 40% 96.1%;
    --muted-foreground: 215.4 16.3% 46.9%;
 
    --accent: 210 40% 96.1%;
    --accent-foreground: 222.2 47.4% 11.2%;
 
    --destructive: 0 84.2% 60.2%;
    --destructive-foreground: 210 40% 98%;

    --border: 214.3 31.8% 91.4%;
    --input: 214.3 31.8% 91.4%;
    --ring: 173 80% 40%; /* teal */
 
    --radius: 0.75rem; /* 12px */
  }
 
  .dark {
    --background: 222.2 84% 4.9%;
    --foreground: 210 40% 98%;
 
    --card: 222.2 84% 4.9%;
    --card-foreground: 210 40% 98%;
 
    --popover: 222.2 84% 4.9%;
    --popover-foreground: 210 40% 98%;
 
    --primary: 173 80% 40%;
    --primary-foreground: 222.2 47.4% 11.2%;
 
    --secondary: 217.2 32.6% 17.5%;
    --secondary-foreground: 210 40% 98%;
 
    --muted: 217.2 32.6% 17.5%;
    --muted-foreground: 215 20.2% 65.1%;
 
    --accent: 217.2 32.6% 17.5%;
    --accent-foreground: 210 40% 98%;
 
    --destructive: 0 62.8% 30.6%;
    --destructive-foreground: 210 40% 98%;
 
    --border: 217.2 32.6% 17.5%;
    --input: 217.2 32.6% 17.5%;
    --ring: 173 80% 40%;
  }
}

@layer base {
  * {
    border-color: hsl(var(--border));
  }
  body {
    @apply bg-background text-foreground antialiased;
    font-feature-settings: "rlig" 1, "calt" 1;
  }
  
  /* Глобальная типографика */
  h1, h2, h3, h4, h5, h6 {
    @apply font-bold tracking-tight text-slate-900 dark:text-white;
  }
}

@layer utilities {
  /* Эффект стекла */
  .glass {
    @apply bg-white/10 backdrop-blur-md border border-white/20;
  }
  
  .glass-dark {
    @apply bg-black/40 backdrop-blur-md border border-white/10;
  }
  
  .text-balance {
    text-wrap: balance;
  }

  /* ==========================================
     HERO ANIMATIONS
     LCP-элементы не должны начинаться с opacity: 0.
     animate-hero-title анимирует только scale — opacity=1 с первого кадра.
     ========================================== */

  .animate-hero-title {
    animation: hero-title-in 0.7s cubic-bezier(0.16, 1, 0.3, 1) both;
  }

  .animate-hero-subtitle {
    animation: hero-subtitle-in 0.7s cubic-bezier(0.16, 1, 0.3, 1) both;
    animation-delay: 50ms;
  }

  /* ==========================================
     ANIMATE-IN COMPATIBILITY LAYER
     Заменяет плагин tailwindcss-animate.
     Воспроизводит те же CSS custom properties и @keyframes enter,
     поэтому все существующие классы (animate-in, fade-in, slide-in-from-*,
     zoom-in-*, fill-mode-both) работают без изменений в JSX-файлах.
     ========================================== */

  /* Базовый класс — запускает анимацию enter с нужными параметрами */
  .animate-in {
    animation-name: enter;
    animation-duration: var(--tw-duration, 150ms);
    --tw-enter-opacity: 1;
    --tw-enter-scale: 1;
    --tw-enter-rotate: 0;
    --tw-enter-translate-x: 0;
    --tw-enter-translate-y: 0;
  }

  /* Opacity: начинает с 0 */
  .fade-in  { --tw-enter-opacity: 0; }

  /* Opacity: заканчивает на 0 (для Toast-выхода) */
  .fade-out { --tw-enter-opacity: 0; }

  /* Scale */
  .zoom-in    { --tw-enter-scale: 0; }
  .zoom-in-95 { --tw-enter-scale: .95; }

  /* Slide from bottom — spacing scale: 2=0.5rem 4=1rem 8=2rem 10=2.5rem */
  .slide-in-from-bottom-2  { --tw-enter-translate-y:  0.5rem; }
  .slide-in-from-bottom-4  { --tw-enter-translate-y:  1rem; }
  .slide-in-from-bottom-8  { --tw-enter-translate-y:  2rem; }
  .slide-in-from-bottom-10 { --tw-enter-translate-y:  2.5rem; }

  /* Slide from top */
  .slide-in-from-top-2 { --tw-enter-translate-y: -0.5rem; }

  /* Slide from left */
  .slide-in-from-left-4 { --tw-enter-translate-x: -1rem; }
  .slide-in-from-left-8 { --tw-enter-translate-x: -2rem; }

  /* Slide from right */
  .slide-in-from-right-4 { --tw-enter-translate-x: 1rem; }

  /* fill-mode — нативный Tailwind не имеет этого класса */
  .fill-mode-both { animation-fill-mode: both; }
}

/* Скроллбары */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  @apply bg-slate-300 dark:bg-slate-700 rounded-full;
}
::-webkit-scrollbar-thumb:hover {
  @apply bg-slate-400 dark:bg-slate-600;
}
.hide-scrollbar::-webkit-scrollbar {
  display: none;
}
.hide-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}
.scrollbar-hide::-webkit-scrollbar {
    display: none;
}
.scrollbar-hide {
    -ms-overflow-style: none;
    scrollbar-width: none;
}

/* ==========================================
   СТИЛИ АДМИН-ПАНЕЛИ (СОХРАНЕНЫ)
   ========================================== */
@layer components {
  .admin-input {
    @apply w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl text-sm font-bold outline-none transition-all duration-300 focus:ring-4 focus:ring-teal-500/10 focus:border-teal-500 focus:bg-white dark:bg-slate-900 dark:border-slate-800 dark:text-white dark:focus:bg-slate-950;
  }

  .admin-label {
    @apply block text-[14px] font-black text-slate-300 uppercase mb-2 ml-1 tracking-widest;
  }

  .admin-section-title {
    @apply text-sm font-black uppercase tracking-[0.2em] text-slate-800 dark:text-white;
  }

  .ai-badge-violet {
    @apply flex items-center gap-2 px-4 py-2 bg-violet-600 text-white rounded-xl text-[12px] font-black uppercase shadow-lg shadow-violet-200 hover:scale-105 transition-all active:scale-95;
  }
}

/* ==========================================
   KEYFRAMES — вне @layer чтобы не удалял Tailwind purge
   ========================================== */

/* hero-title-in: только масштаб, opacity=1 — LCP фиксируется мгновенно */
@keyframes hero-title-in {
  from { transform: scale(0.96); }
  to   { transform: scale(1); }
}

/* hero-subtitle-in: opacity от 0.01 (не 0!) — не влияет на LCP */
@keyframes hero-subtitle-in {
  from {
    opacity: 0.01;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* enter: используется animate-in через CSS custom properties.
   Воспроизводит поведение tailwindcss-animate без самого плагина. */
@keyframes enter {
  from {
    opacity: var(--tw-enter-opacity, 1);
    transform:
      translate3d(
        var(--tw-enter-translate-x, 0),
        var(--tw-enter-translate-y, 0),
        0
      )
      scale3d(
        var(--tw-enter-scale, 1),
        var(--tw-enter-scale, 1),
        var(--tw-enter-scale, 1)
      )
      rotate(var(--tw-enter-rotate, 0));
  }
}
/* =============================================
   ACCOUNT LAYOUT — Отступ от фиксированного Header
   ============================================= */

:root {
  --header-height: 82px;     /* мобильная версия */
}

@media (min-width: 768px) {
  :root {
    --header-height: 104px;  /* md и выше */
  }
}

@media (min-width: 1024px) {
  :root {
    --header-height: 112px;  /* lg и выше — небольшой запас */
  }
}
/* Анимация SUP-доски */
@keyframes float-sup {
  0%, 100% { transform: translateY(-10px); }
  50% { transform: translateY(10px); }
}
.animate-float-sup {
  animation: float-sup 6s ease-in-out infinite;
}

"use client";

import React, { useRef, useEffect } from 'react';
import Image from 'next/image';
import { ArrowDown } from 'lucide-react';
import { DirectionData, THEMES } from '@/data/directionsData';

interface DirectionHeroProps {
  data: DirectionData;
}

export default function DirectionHero({ data }: DirectionHeroProps) {
  const bgRef = useRef<HTMLDivElement>(null);
  const txtRef = useRef<HTMLDivElement>(null);

  const theme = THEMES[data.theme];

  useEffect(() => {
    // Пишем в DOM напрямую — без setState, без ре-рендера React
    const onScroll = () => {
      const y = window.scrollY;
      const viewportH = window.innerHeight || 800;

      if (bgRef.current) {
        bgRef.current.style.transform = `translateY(${y * 0.4}px)`;
        const bgOp = Math.max(0.3, 1 - (y / (viewportH * 0.8)) * 0.7);
        bgRef.current.style.opacity = String(bgOp);
      }

      if (txtRef.current) {
        txtRef.current.style.transform = `translateY(${y * 0.5}px)`;
        const txtOp = Math.max(0, 1 - y / (viewportH * 0.5));
        txtRef.current.style.opacity = String(txtOp);
      }
    };

    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  const handleScrollDown = () => {
    window.scrollTo({ top: window.innerHeight - 80, behavior: 'smooth' });
  };

  return (
    <section className="relative h-[100svh] min-h-[600px] w-full flex items-center justify-center overflow-hidden bg-slate-950">

      {/* 1. МЕДИАСЛОЙ */}
      <div
        ref={bgRef}
        className="absolute inset-0 z-0 pointer-events-none will-change-transform"
      >
        {data.hero.videoUrl ? (
          <video
            autoPlay loop muted playsInline
            className="absolute inset-0 w-full h-full object-cover"
          >
            <source src={data.hero.videoUrl} type="video/mp4" />
          </video>
        ) : (
          <Image
            src={data.hero.imageUrl}
            alt={data.hero.title}
            fill
            priority
            fetchPriority="high"
            quality={75}
            className="object-cover"
            sizes="100vw"
          />
        )}

        <div className="absolute inset-0 bg-slate-950/30 mix-blend-multiply" />
        <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-slate-950/40 to-slate-950/10" />
        <div
          className="absolute inset-0 opacity-40 mix-blend-overlay pointer-events-none"
          style={{
            background: `radial-gradient(circle at center, transparent 0%, ${theme.glow} 100%)`,
          }}
        />
      </div>

      {/* 2. КОНТЕНТ */}
      <div
        ref={txtRef}
        className="relative z-10 container mx-auto px-4 flex flex-col items-center text-center mt-20 will-change-transform"
        style={{ transition: 'none' }}
      >
        {/* Бейдж — не LCP, fade-in допустим */}
        <div
          className="animate-in fade-in slide-in-from-bottom-4 duration-700 inline-flex items-center gap-2 px-4 py-1.5 rounded-full border backdrop-blur-md mb-6 sm:mb-8 shadow-2xl"
          style={{
            backgroundColor: `${theme.glow.replace('0.4', '0.1')}`,
            borderColor: `${theme.glow.replace('0.4', '0.3')}`,
          }}
        >
          <span
            className="text-[12px] sm:text-xs font-black uppercase tracking-[0.2em]"
            style={{ color: theme.hex }}
          >
            {data.hero.badge}
          </span>
        </div>

        {/* H1 — LCP-элемент. animate-hero-title анимирует только scale,
            opacity остаётся 1 с первого кадра — Lighthouse фиксирует LCP мгновенно */}
        <h1 className="animate-hero-title text-4xl xs:text-5xl sm:text-6xl md:text-8xl font-black text-white uppercase tracking-tighter leading-[0.95] mb-6 drop-shadow-2xl max-w-5xl">
          {data.hero.title}
        </h1>

        {/* Подзаголовок — не LCP, fade-in с задержкой допустим */}
        <p className="animate-hero-subtitle text-sm sm:text-lg md:text-xl text-slate-300 font-medium max-w-2xl leading-relaxed drop-shadow-md">
          {data.hero.subtitle}
        </p>
      </div>

      {/* 3. КНОПКА СКРОЛЛА */}
      <div className="absolute bottom-8 sm:bottom-12 left-0 right-0 z-20 flex justify-center pointer-events-none">
        <button
          onClick={handleScrollDown}
          className="flex flex-col items-center gap-3 sm:gap-4 group cursor-pointer pointer-events-auto animate-in fade-in duration-1000 delay-500 fill-mode-both"
        >
          <div
            className="w-12 h-12 sm:w-14 sm:h-14 rounded-full border flex items-center justify-center transition-all duration-500 shadow-lg backdrop-blur-sm"
            style={{
              borderColor: `${theme.glow.replace('0.4', '0.3')}`,
              backgroundColor: 'rgba(255,255,255,0.05)',
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.backgroundColor = theme.hex;
              e.currentTarget.style.borderColor = theme.hex;
              e.currentTarget.style.boxShadow = `0 0 20px ${theme.glow}`;
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.backgroundColor = 'rgba(255,255,255,0.05)';
              e.currentTarget.style.borderColor = `${theme.glow.replace('0.4', '0.3')}`;
              e.currentTarget.style.boxShadow = 'none';
            }}
          >
            <ArrowDown
              className="text-white group-hover:text-slate-900 animate-bounce w-5 h-5 sm:w-6 sm:h-6"
              strokeWidth={2}
            />
          </div>
        </button>
      </div>
    </section>
  );
}

