                                              )}
                                            </td>
                                            <td className="px-6 py-4 text-xs font-medium text-slate-600 whitespace-normal">
                                              {p.isMain && p.comment ? <span className="italic">«{p.comment}»</span> : null}
                                            </td>
                                          </tr>
                                        ))}
                                      </tbody>
                                    </table>
                                    
