                <XIcon size={24} />
              </button>
            </div>
            
            <div className="p-4 overflow-y-auto bg-slate-100 flex items-center justify-center relative min-h-[300px]">
              {receiptModal.booking.payment_proof_url ? (
                  <img 
                    src={receiptModal.booking.payment_proof_url} 
