// src/features/tours/types.ts

// ==========================================
// 1. ТИПЫ ДЛЯ РЕЛЯЦИОННЫХ ДАТ
// ==========================================
export interface TourDateItem {
  id: string;
  date: string;
  endDate?: string | null;
  time?: string | null;
