// ==========================================
export interface GuideInfo {
  id: string;
  name: string;
  role: string;
  image?: string | null;
  bio?: string | null;
  instagram?: string | null;
  telegram?: string | null;
}

// ==========================================
// 3. ВЛОЖЕННЫЕ ТИПЫ ДЛЯ JSON-ПОЛЕЙ
// ==========================================
export interface TourHighlight {
  title: string;
  description?: string;
  desc?: string;
  icon?: string;
}

export interface TourFaq {
  question: string;
  answer: string;
}

export interface TourChecklist {
