"use client";

import React, { useState } from 'react';
import { X, Save, Tent, Mountain, Waves, Compass, Map, Sun, Snowflake, TreePine, Bike, Footprints, Loader2, MapPin, Anchor, Flame, Star } from 'lucide-react';

// ✅ ИСПРАВЛЕНО: Объявляем цвета прямо здесь, чтобы не зависеть от schemas.ts и не ронять билд Vercel
const CATEGORY_COLORS = [
  'slate', 'teal', 'emerald', 'sky', 'blue',
  'violet', 'pink', 'rose', 'orange', 'amber',
] as const;

const AVAILABLE_ICONS = [
  { name: 'Compass', icon: Compass, label: 'Компас (универсально)' },
  { name: 'Tent', icon: Tent, label: 'Палатка (походы)' },
  { name: 'Mountain', icon: Mountain, label: 'Горы (треккинг)' },
  { name: 'Waves', icon: Waves, label: 'Волны (вода, байдарки, SUP)' },
  { name: 'Map', icon: Map, label: 'Карта (экскурсии)' },
  { name: 'Sun', icon: Sun, label: 'Солнце (лето, тепло)' },
  { name: 'Snowflake', icon: Snowflake, label: 'Снежинка (зима)' },
  { name: 'TreePine', icon: TreePine, label: 'Лес (природа)' },
  { name: 'Bike', icon: Bike, label: 'Велосипед' },
  { name: 'Footprints', icon: Footprints, label: 'Следы (пешие)' },
  { name: 'MapPin', icon: MapPin, label: 'Локация (местные)' },
  { name: 'Anchor', icon: Anchor, label: 'Якорь' },
  { name: 'Flame', icon: Flame, label: 'Костер (выживание)' },
  { name: 'Star', icon: Star, label: 'Звезда (хит, особенное)' },
];

const AVAILABLE_COLORS = CATEGORY_COLORS.map(key => ({
  key,
  bgClass: `bg-${key}-500` as const,
}));

// === СТРОГАЯ ТИПИЗАЦИЯ ===
export interface CategoryData {
  id?: string;
  title?: string;
  slug?: string;
  icon?: string;
  color?: string;
  sortOrder?: number;
  sort_order?: number;
  isActive?: boolean;
  is_active?: boolean;
}

export interface CategoryFormData {
  id: string;
  title: string;
  slug: string;
  icon: string;
  color: string;
  sort_order: number | string;
  is_active: boolean;
}

interface Props {
  initialData?: CategoryData | null;
  type: 'tour' | 'blog';
  onClose: () => void;
  onSubmit: (data: Record<string, unknown>) => Promise<void>;
}

export default function CategoryForm({ initialData, type, onClose, onSubmit }: Props) {
  const [loading, setLoading] = useState(false);
  
  const [formData, setFormData] = useState<CategoryFormData>({
    id: initialData?.id || '',
    title: initialData?.title || '',
    slug: initialData?.slug || '',
    icon: initialData?.icon || 'Compass',
    color: initialData?.color || 'teal',
    sort_order: initialData?.sortOrder ?? initialData?.sort_order ?? 0,
    is_active: initialData?.isActive ?? initialData?.is_active ?? true,
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name as keyof CategoryFormData]: type === 'checkbox' ? checked : value
    }));
  };

  const handleTitleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const title = e.target.value;
    if (!initialData?.id) {
      const slug = title.toLowerCase().replace(/[^a-z0-9а-яё]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '');
      setFormData(prev => ({ ...prev, title, slug }));
    } else {
      setFormData(prev => ({ ...prev, title }));
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      // Приводим к Record<string, unknown> согласно интерфейсу Props
      await onSubmit(formData as unknown as Record<string, unknown>);
    } catch (error) {
      console.error('Submit error:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-sm">
      <div className="w-full max-w-lg bg-slate-900 border border-slate-700 rounded-2xl shadow-2xl flex flex-col max-h-[90vh]">
        
        <div className="flex justify-between items-center p-6 border-b border-slate-800">
          <h2 className="text-xl font-bold text-white">
            {initialData?.id ? 'Редактировать' : 'Новая'}{' '}
            {type === 'tour' ? 'категория туров' : 'категория блога'}
          </h2>
          <button onClick={onClose} className="text-slate-300 hover:text-white transition-colors">
            <X size={24} />
          </button>
        </div>

        <div className="p-6 overflow-y-auto custom-scrollbar">
          <form id="category-form" onSubmit={handleSubmit} className="space-y-5">
            
            <div className="space-y-1">
              <label className="text-sm font-medium text-slate-300">Название категории *</label>
              <input
                required
                name="title"
                value={formData.title}
                onChange={handleTitleChange}
                placeholder="Например: Сплавы на байдарках"
                className="w-full bg-slate-950 border border-slate-800 rounded-xl p-3 text-white focus:border-teal-500 outline-none"
              />
            </div>

            <div className="space-y-1">
              <label className="text-sm font-medium text-slate-300">Slug (URL) *</label>
              <input
                required
                name="slug"
                value={formData.slug}
                onChange={handleChange}
                placeholder="Например: kayaking"
                className="w-full bg-slate-950 border border-slate-800 rounded-xl p-3 text-white focus:border-teal-500 outline-none font-mono text-sm"
              />
            </div>

            {type === 'tour' && (
              <div className="space-y-3">
                <label className="text-sm font-medium text-slate-300">Иконка категории</label>
                <div className="grid grid-cols-4 sm:grid-cols-5 gap-2">
                  {AVAILABLE_ICONS.map((item) => {
                    const isSelected = formData.icon === item.name;
                    return (
                      <button
                        key={item.name}
                        type="button"
                        onClick={() => setFormData(prev => ({ ...prev, icon: item.name }))}
                        title={item.label}
                        className={`flex flex-col items-center justify-center p-3 rounded-xl border transition-all ${
                          isSelected
                            ? 'bg-teal-500/20 border-teal-500 text-teal-400'
                            : 'bg-slate-950 border-slate-800 text-slate-300 hover:border-slate-600 hover:text-slate-300'
                        }`}
                      >
                        <item.icon size={24} strokeWidth={isSelected ? 2.5 : 2} />
                        <span className="text-[12px] mt-1.5 opacity-70 truncate w-full text-center">
                          {item.name}
                        </span>
                      </button>
                    );
                  })}
                </div>
              </div>
            )}

            {type === 'tour' && (
              <div className="space-y-3 border-t border-slate-800 pt-4">
                <label className="text-sm font-medium text-slate-300">Фирменный цвет категории</label>
                <div className="flex flex-wrap gap-3">
                  {AVAILABLE_COLORS.map((color) => {
                    const isSelected = formData.color === color.key;
                    return (
                      <button
                        key={color.key}
                        type="button"
                        onClick={() => setFormData(prev => ({ ...prev, color: color.key }))}
                        className={`w-10 h-10 rounded-full transition-all flex items-center justify-center ${color.bgClass} ${
                          isSelected ? 'ring-2 ring-white ring-offset-2 ring-offset-slate-900 scale-110 shadow-lg' : 'opacity-50 hover:opacity-100 hover:scale-105'
                        }`}
                        title={color.key}
                      />
                    );
                  })}
                </div>
              </div>
            )}

            <div className="grid grid-cols-2 gap-4 border-t border-slate-800 pt-4">
              <div className="space-y-1">
                <label className="text-sm font-medium text-slate-300">Порядок сортировки</label>
                <input
                  type="number"
                  name="sort_order"
                  value={formData.sort_order}
                  onChange={handleChange}
                  placeholder="0"
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl p-3 text-white focus:border-teal-500 outline-none"
                />
                <p className="text-[11px] text-slate-300">Меньше цифра = выше в списке</p>
              </div>

              <div className="flex items-center mt-6">
                <label className="flex items-center gap-3 cursor-pointer group">
                  <div className="relative">
                    <input
                      type="checkbox"
                      name="is_active"
                      checked={formData.is_active}
                      onChange={handleChange}
                      className="sr-only"
                    />
                    <div className={`block w-10 h-6 rounded-full transition-colors ${formData.is_active ? 'bg-teal-500' : 'bg-slate-700'}`}></div>
                    <div className={`absolute left-1 top-1 bg-white w-4 h-4 rounded-full transition-transform ${formData.is_active ? 'translate-x-4' : ''}`}></div>
                  </div>
                  <span className="text-sm font-medium text-slate-300 group-hover:text-white transition-colors">
                    Активна
                  </span>
                </label>
              </div>
            </div>

          </form>
        </div>

        <div className="p-6 border-t border-slate-800 bg-slate-900/50">
          <button
            type="submit"
            form="category-form"
            disabled={loading}
            className="w-full py-3 bg-teal-500 hover:bg-teal-400 text-slate-900 font-bold rounded-xl transition-all flex items-center justify-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
          >
            {loading ? <Loader2 className="animate-spin" size={20} /> : <Save size={20} />}
            {loading ? 'Сохранение...' : 'Сохранить категорию'}
          </button>
        </div>

      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { ChevronDown, MessageCircle, Sparkles } from 'lucide-react';
import { useModalStore } from '@/shared/store/useModalStore';
import { clsx } from "clsx";
import { twMerge } from "tailwind-merge";
import { useInView } from '@/hooks/useInView';

function cn(...inputs: (string | undefined | null | false)[]) {
  return twMerge(clsx(inputs));
}

const FAQ_DATA = [
    { 
        q: "А если я буду тормозить группу?", 
        a: "Это самый частый страх! Мы всегда идем по среднему темпу, учитывая темп медленных участников. Делаем привалы. У нас не спортивные забеги на время, а экспедиции для удовольствия (если это не влияет на безопасность маршрута)." 
    },
    { 
        q: "Что с визами и документами?", 
        a: "Мы выбираем страны, где не нужны визы. Нужен действующий биометрический паспорт Украины или Молдовы со сроком действия не менее 6 месяцев до его окончания." 
    },
    { 
        q: "Чем мы будем питаться в горах?", 
        a: "Формат питания зависит от конкретного тура. Это может быть только завтрак, завтрак и ужин, или полноценное трехразовое питание. В любом случае, мы всегда обеспечиваем вкусную и сытную походную еду, которая поможет восстановить силы."
    }
];

export default function HikesFAQ() {
    const [openIndex, setOpenIndex] = useState<number | null>(null);
    const openContactModal = useModalStore((state) => state.openContactModal);
    
    const faqView = useInView({ threshold: 0.1, rootMargin: '-30px' });
    const ctaView = useInView({ threshold: 0.1, rootMargin: '-30px' });

    return (
        <section className="py-8 md:py-16 bg-stone-950 text-stone-100 border-t border-white/5 relative overflow-hidden">
            
            <div className="absolute top-0 right-1/4 w-[600px] h-[600px] bg-teal-900/10 md:blur-[150px] rounded-full pointer-events-none" />

            <div className="container mx-auto px-4 max-w-6xl relative z-10">
                
                <div className="grid lg:grid-cols-12 gap-10 md:gap-16 items-start">
                    
                    {/* ЛЕВАЯ КОЛОНКА: FAQ */}
                    <div className="lg:col-span-7">
                        <div
                            ref={faqView.ref}
                            style={{ opacity: faqView.inView ? 1 : 0, transform: faqView.inView ? 'translateX(0)' : 'translateX(-20px)', transition: 'opacity 0.6s ease, transform 0.6s ease' }}
                            className="text-left"
                        >
                           <h2 className="text-5xl md:text-7xl font-black uppercase tracking-tighter text-white mb-8 md:mb-12">
                              FAQ<span className="text-teal-500">.</span>
                           </h2>
                            
                            <div className="space-y-3 md:space-y-4">
                                {FAQ_DATA.map((item, index) => {
                                    const isOpen = openIndex === index;
                                    return (
                                        <div key={index} className="bg-stone-900/50 backdrop-blur-sm border border-stone-800 rounded-2xl overflow-hidden hover:border-teal-900/50 transition-colors shadow-lg">
                                            <button
                                                onClick={() => setOpenIndex(isOpen ? null : index)}
                                                aria-expanded={isOpen}
                                                className="w-full flex items-center justify-between p-5 md:p-6 text-left focus:outline-none group"
                                            >
                                                <span className="font-bold pr-4 text-[14px] md:text-base text-stone-200 group-hover:text-white transition-colors">
                                                    {item.q}
                                                </span>
                                                <div className={cn("w-8 h-8 rounded-full flex items-center justify-center shrink-0 transition-all duration-300", isOpen ? "rotate-180 bg-teal-900/30 text-teal-400" : "bg-stone-800 text-stone-400 group-hover:bg-stone-700")}>
                                                    <ChevronDown size={18} />
                                                </div>
                                            </button>
                                            
                                            {/* Нативный CSS Grid Аккордеон */}
                                            <div className={cn(
                                                "grid transition-all duration-300 ease-in-out",
                                                isOpen ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0"
                                            )}>
                                                <div className="overflow-hidden">
                                                    <div className="px-5 md:px-6 pb-5 md:pb-6 text-[14px] md:text-base text-stone-400 border-t border-stone-800 pt-4 font-medium leading-relaxed">
                                                        {item.a}
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    )
                                })}
                            </div>
                        </div>
                    </div>

                    {/* ПРАВАЯ КОЛОНКА: ФИНАЛЬНЫЙ CTA */}
                    <div className="lg:col-span-5">
                        <div
                            ref={ctaView.ref}
                            style={{ opacity: ctaView.inView ? 1 : 0, transform: ctaView.inView ? 'translateX(0)' : 'translateX(20px)', transition: 'opacity 0.6s ease, transform 0.6s ease' }}
                            className="bg-stone-900/60 backdrop-blur-md border border-stone-700/50 rounded-[2rem] md:rounded-[2.5rem] p-6 md:p-10 shadow-2xl relative overflow-hidden lg:sticky lg:top-24"
                        >
                            <div className="absolute top-0 right-0 w-48 h-48 bg-teal-500/10 blur-[50px] rounded-full pointer-events-none" />
                            
                            <Sparkles className="w-8 h-8 md:w-10 md:h-10 text-teal-500 mb-5 md:mb-6" />

                            <h2 className="text-2xl md:text-3xl font-black uppercase tracking-tighter mb-4 text-stone-100 leading-tight">
                                Готовы к <span className="text-teal-400">перезагрузке?</span>
                            </h2>
                            <p className="text-stone-400 mb-8 text-[14px] md:text-base font-medium leading-relaxed">
                                Свяжитесь с нами, чтобы узнать даты ближайших экспедиций, подобрать комфортный маршрут или задать любые вопросы лично гиду.
                            </p>

                            <div className="flex flex-col relative z-10">
                                <button 
                                   onClick={() => openContactModal('Вопрос по турам в горы', 'TOUR')}
                                    className="w-full py-4 bg-teal-600 text-white font-bold uppercase tracking-wider text-[13px] md:text-sm rounded-xl hover:bg-teal-500 hover:scale-[1.02] active:scale-[0.98] transition-all flex items-center justify-center gap-2 shadow-[0_0_20px_rgba(20,184,166,0.3)]"
                                >
                                    <MessageCircle size={18} />
                                    <span>Спросить о туре</span>
                                </button>
                            </div>
                        </div>
                    </div>

                </div>
            </div>

        </section>
    );
}

