"use client";

import React from 'react';
import { Bus, Tent, Utensils, SignalHigh, ArrowRight } from 'lucide-react';
import { useInView } from '@/hooks/useInView';

const logisticsData = [
    {
        icon: Bus,
        title: "Транспорт",
        desc: "Едем транспорте 8-20 человек прямо из ПМР/Молдовы до точки старта маршрута."
    },
    {
        icon: Tent,
        title: "Ночевки",
        desc: "Спим в гостевых домах, горных приютах, отелях или в палатках в зависимости от маршрута и формата тура. Детали всегда указаны в программе."
    },
    {
        icon: Utensils,
        title: "Питание",
        desc: "Готовим вкусную походную еду на газовых горелках или костре. Учитываем пожелания: если вы вегетарианец — просто предупредите нас заранее."
    },
    {
        icon: SignalHigh,
        title: "Связь",
        desc: "В горах связь часто нестабильна или отсутствует. Это отличный повод для цифрового детокса. Предупредите близких, что можете быть вне зоны."
    }
];

export default function HikesLogistics() {
    const cardsView = useInView({ threshold: 0.1, rootMargin: '-30px' });

    return (
        <section className="py-12 md:py-24 relative overflow-hidden">
            <div className="container mx-auto px-4 max-w-7xl">
                
                {/* --- 1. БЛОК С ЦИТАТОЙ --- */}
                <div className="w-full bg-slate-900 border border-white/5 rounded-[2rem] p-6 md:p-12 mb-16 relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-64 h-64 bg-teal-500/5 blur-[80px] rounded-full pointer-events-none" />
                    
                    <div className="relative z-10 flex flex-col lg:flex-row gap-8 lg:gap-16 items-start lg:items-center">
                        <div className="flex-1 min-w-0"> 
                            <h2 className="text-3xl md:text-5xl font-black text-white uppercase tracking-tighter leading-[1.1] mb-6">
                                В горах нет <br className="hidden md:block"/>
                                <span className="text-teal-500">случайных людей</span>
                            </h2>
                            <p className="text-slate-300 text-sm md:text-base leading-relaxed font-medium mb-8">
                                «Тур в горы — это ваш личный отдых, а не испытание на прочность. Моя задача как гида — взять на себя всю логистику, чтобы вы могли просто идти, дышать и впитывать красоту вокруг. Мы всегда идем в среднем темпе комфортном для медленных и быстрых участников. Никто никого не бросает».
                            </p>
                            
                            <div className="flex items-center gap-4 pt-6 border-t border-white/10 w-full md:w-max">
                                <div className="w-12 h-12 rounded-full bg-slate-800 border border-white/10 flex items-center justify-center shrink-0">
                                    <span className="text-lg font-black text-slate-300">Р</span>
                                </div>
                                <div>
                                    <div className="text-white font-bold text-sm md:text-base">Роман Санду</div>
                                    <div className="text-teal-500 text-[12px] md:text-xs font-bold uppercase tracking-widest">Туристический гид</div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                {/* --- 2. КАРТОЧКИ ЛОГИСТИКИ --- */}
                <div ref={cardsView.ref}>
                    <div className="flex md:hidden items-center gap-2 mb-4 text-slate-300 pl-1">
                        <ArrowRight size={16} className="text-teal-500 animate-pulse" />
                        <span className="text-[11px] font-bold uppercase tracking-widest">Листайте вбок</span>
                    </div>

                    <div className="flex overflow-x-auto snap-x snap-mandatory gap-4 pb-8 -mx-4 px-4 md:mx-0 md:px-0 md:grid md:grid-cols-2 lg:grid-cols-4 [&::-webkit-scrollbar]:hidden [-ms-overflow-style:none] [scrollbar-width:none]">
                        
                        {logisticsData.map((item, idx) => {
                            const Icon = item.icon;
                            return (
                                <div 
                                    key={idx}
                                    style={{ opacity: cardsView.inView ? 1 : 0, transform: cardsView.inView ? 'translateY(0)' : 'translateY(20px)', transition: `opacity 0.6s ease ${idx * 0.1}s, transform 0.6s ease ${idx * 0.1}s` }}
                                    className="w-[85vw] sm:w-[300px] md:w-auto shrink-0 snap-start bg-slate-900/50 backdrop-blur-sm border border-white/5 rounded-3xl p-6 md:p-8 hover:bg-slate-900 hover:border-teal-500/30 transition-all group flex flex-col"
                                >
                                    <div className="w-12 h-12 rounded-2xl bg-slate-800 border border-white/5 flex items-center justify-center mb-6 group-hover:scale-110 transition-transform shadow-lg">
                                        <Icon className="text-teal-500" size={24} strokeWidth={1.5} />
                                    </div>
                                    <h3 className="text-xl font-black text-white mb-4">{item.title}</h3>
                                    <p className="text-sm text-slate-300 leading-relaxed font-medium">
                                        {item.desc}
                                    </p>
                                </div>
                            );
                        })}

                    </div>
                </div>

            </div>
        </section>
    );
}

files.src/features/directions/sup/components/S:
'use client';

import { useState } from 'react';
import { type ElementType } from 'react';
import { Clock, MapPin, Users, Star, Compass, ArrowRight } from 'lucide-react';

// 1. Описываем, как выглядит маршрут
type RouteType = { name: string; dist: string; time: string };

// 2. Описываем общую структуру карточки
type CatalogItemType = {
  id: string;
  title: string;
  badge: string;
  icon: ElementType;
  description: string;
  duration: string;
  format: string;
  features: string[];
  locations?: string[]; 
  routes?: RouteType[]; 
};

// 3. Данные каталога
const CATALOG_DATA: Record<'lessons' | 'tours', CatalogItemType> = {
  lessons: {
    id: 'lessons',
    title: "SUP-Занятие",
    badge: "Для новичков",
    icon: Star,
    description: "Идеальный старт. Сфокусируемся на технике, балансе и уверенности, чтобы вы могли наслаждаться прогулками без страха.",
    duration: "1.5 - 2 часа",
    format: "Обучение на суше + практика в акватории. Доступно самостоятельно с 10 лет.",
    features: ["Снаряжение включено", "Инструктаж и сопровождение", "Геромочехол для телефона"],
    locations: ["г. Тирасполь", "г. Бендеры", "с. Суклея"],
  },
  tours: {
    id: 'tours',
    title: "SUP-Прогулка",
    badge: "Мини-путешествие",
    icon: Compass,
    description: "Полноценные сплавы по живописным маршрутам. Для тех, кто хочет ветра в волосах и новых горизонтов.",
    duration: "2 - 6 часов",
    format: "Сплав 10-17 км. Доступно с 10 лет (или с 3 лет на доске с родителем).",
    features: ["Снаряжение включено", "Инструктаж и сопровождение", "Геромочехол для телефона", "Красивые фото на воде"],
    routes: [
      { name: "Терновка – Тирасполь", dist: "8 км", time: "2 ч" },
      { name: "Бычок – Бендеры", dist: "10 км", time: "3 ч" },
      { name: "Суклея – Слободзея", dist: "15 км", time: "4 ч" },
      { name: "Тирасполь – Карагаш", dist: "17 км", time: "5 ч" }
    ],
  }
};

export default function SupCatalog() {
  const [activeTab, setActiveTab] = useState<'lessons' | 'tours'>('lessons');
  const data = CATALOG_DATA[activeTab];

  return (
    <section className="py-8 md:py-16 bg-slate-950 relative overflow-hidden border-t border-white/5">
      <div className="container mx-auto px-4 max-w-5xl relative z-10">
        
        {/* HEADER */}
        <div className="flex flex-col items-center text-center mb-6 md:mb-10">
            <h2 className="text-3xl md:text-5xl lg:text-6xl font-black text-white uppercase tracking-tighter">
                Выберите свой <br className="hidden md:block" /><span className="text-teal-500">Формат</span>
            </h2>
        </div>

        {/* STICKY SWITCHER (CSS-only ползунок) */}
        <div className="sticky top-[70px] md:top-[90px] z-50 py-3 mb-6 md:mb-10 bg-slate-950/90 backdrop-blur-xl -mx-4 px-4 md:mx-0 md:px-0 flex justify-center border-b border-white/5 md:border-none">
            <div className="relative bg-slate-900 p-1.5 rounded-2xl border border-white/5 inline-flex shadow-2xl w-full sm:w-auto overflow-hidden">
                {/* CSS ползунок */}
                <div 
                    className={`absolute top-1.5 bottom-1.5 w-[calc(50%-6px)] bg-teal-500 rounded-xl shadow-md transition-transform duration-300 ease-out z-0 ${activeTab === 'tours' ? 'translate-x-[calc(100%+12px)]' : 'translate-x-0'}`}
                />
                
                <button 
                    onClick={() => setActiveTab('lessons')}
                    className={`relative z-10 flex-1 sm:flex-none px-4 md:px-8 py-3 rounded-xl text-[12px] md:text-sm font-bold uppercase tracking-widest transition-colors duration-300 ${activeTab === 'lessons' ? "text-slate-950" : "text-slate-300 hover:text-white"}`}
                >
                    ПРОГУЛКИ
                </button>
                <button 
                    onClick={() => setActiveTab('tours')}
                    className={`relative z-10 flex-1 sm:flex-none px-4 md:px-8 py-3 rounded-xl text-[12px] md:text-sm font-bold uppercase tracking-widest transition-colors duration-300 ${activeTab === 'tours' ? "text-slate-950" : "text-slate-300 hover:text-white"}`}
                >
                    СПЛАВЫ
                </button>
            </div>
        </div>

        {/* CONTENT CARD (CSS Fade-in) */}
        <div 
            key={activeTab} // Ключ заставляет React перерисовать блок (запуская анимацию Tailwind)
            className="bg-slate-900/40 border border-white/5 rounded-[2rem] md:rounded-[2.5rem] p-5 md:p-12 backdrop-blur-md flex flex-col shadow-xl animate-in fade-in zoom-in-95 duration-300"
        >
            {/* 1. Бейдж и Заголовок */}
            <div className="mb-6 md:mb-8">
                <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-teal-500/10 text-teal-400 text-[12px] font-bold uppercase tracking-widest mb-3 md:mb-4">
                    {data.badge}
                </div>
                <h3 className="text-3xl md:text-5xl font-black text-white uppercase tracking-tight mb-3 md:mb-4 leading-none">
                    {data.title}
                </h3>
                <p className="text-[14px] md:text-lg text-slate-300 leading-relaxed font-medium max-w-3xl">
                    {data.description}
                </p>
            </div>

            {/* 2. СЕТКА ХАРАКТЕРИСТИК */}
            <div className="grid grid-cols-2 md:grid-cols-3 gap-5 md:gap-6 mb-6 md:mb-10 pb-6 md:pb-10 border-b border-white/5">
                <div className="flex flex-col sm:flex-row items-start gap-3 md:gap-4">
                    <div className="w-10 h-10 md:w-12 md:h-12 rounded-xl md:rounded-2xl bg-slate-950 flex items-center justify-center shrink-0 text-teal-500 border border-white/5 shadow-inner">
                        <Clock size={20} className="md:w-6 md:h-6" />
                    </div>
                    <div>
                        <p className="text-[12px] uppercase font-bold text-slate-300 tracking-widest mb-1">Время</p>
                        <p className="text-[14px] md:text-lg text-white font-black">{data.duration}</p>
                    </div>
                </div>
                
                <div className="flex flex-col sm:flex-row items-start gap-3 md:gap-4">
                    <div className="w-10 h-10 md:w-12 md:h-12 rounded-xl md:rounded-2xl bg-slate-950 flex items-center justify-center shrink-0 text-teal-500 border border-white/5 shadow-inner">
                        <Users size={20} className="md:w-6 md:h-6" />
                    </div>
                    <div>
                        <p className="text-[12px] uppercase font-bold text-slate-300 tracking-widest mb-1">Особенности</p>
                        <p className="text-[13px] md:text-sm text-white font-bold leading-snug">{data.format}</p>
                    </div>
                </div>

                <div className="col-span-2 md:col-span-1 flex flex-col justify-center gap-2 border-t md:border-t-0 md:border-l border-white/5 pt-4 md:pt-0 pl-0 md:pl-6 mt-1 md:mt-0">
                    {data.features.map((feat, idx) => (
                        <div key={idx} className="flex items-center gap-2 text-[13px] md:text-sm text-slate-300 font-medium">
                            <span className="text-teal-400 font-black shrink-0">✓</span> 
                            <span className="leading-snug">{feat}</span>
                        </div>
                    ))}
                </div>
            </div>

            {/* 3. МАРШРУТЫ И ЛОКАЦИИ */}
            <div className="bg-slate-950/50 rounded-[1.5rem] md:rounded-[2rem] p-5 md:p-8 border border-white/5 relative">
                <p className="text-[12px] md:text-sm font-bold text-teal-500 uppercase tracking-widest mb-4 md:mb-6 flex items-center gap-2">
                    <MapPin size={16} /> 
                    {activeTab === 'lessons' ? "Доступные акватории:" : "Популярные маршруты:"}
                </p>
                
                <div className="flex overflow-x-auto snap-x snap-mandatory gap-3 pb-4 md:pb-0 -mx-5 px-5 md:mx-0 md:px-0 md:flex-wrap [&::-webkit-scrollbar]:hidden [-ms-overflow-style:none] [scrollbar-width:none]">
                    {activeTab === 'lessons' 
                        ? data.locations?.map(loc => (
                            <span key={loc} className="shrink-0 snap-center px-4 md:px-5 py-2.5 md:py-3 bg-slate-900 rounded-xl text-[13px] md:text-sm font-bold text-white border border-white/5 hover:border-teal-500/30 transition-colors shadow-sm">
                                {loc}
                            </span>
                          ))
                        : data.routes?.map(route => (
                            <div key={route.name} className="shrink-0 snap-center w-[75vw] md:w-auto flex flex-col p-4 bg-slate-900 rounded-xl border border-white/5 hover:border-teal-500/30 transition-colors md:min-w-[180px] shadow-sm">
                                <span className="text-[14px] md:text-sm font-black text-white mb-1.5">{route.name}</span>
                                <span className="text-[11px] md:text-xs text-slate-300 uppercase tracking-widest font-bold">
                                    {route.dist} <span className="text-teal-500 mx-1.5">•</span> {route.time}
                                </span>
                            </div>
                          ))
                    }
                </div>

                {activeTab === 'tours' && (
                      <div className="flex md:hidden items-center gap-2 mb-4 text-slate-300 pl-1">
                                  <ArrowRight size={16} className="text-teal-500 animate-pulse" />
                                  <span className="text-[11px] font-bold uppercase tracking-widest">Листайте вбок</span>
                              </div>
                )}
            </div>

        </div>
      </div>
    </section>
  );
}

"use client";

import Image from 'next/image';
import { 
