import React from 'react';
import dynamic from 'next/dynamic';
import { Tour, TourPreview } from '@/features/tours/types';

// ✅ Above-fold (Первый экран) — статические импорты (попадают в initial bundle)
import TourStickyNav from './TourStickyNav';
import TourHero from './TourHero';
import TourDirectionBanner from './TourDirectionBanner';
import TourLegalLinks from './TourLegalLinks';

// ✅ Below-fold (Ниже первого экрана) — ленивые импорты (разгружают Main Thread)
const TourStats         = dynamic(() => import('./TourStats'));
const TourLogistics     = dynamic(() => import('./TourLogistics'));
const TourSidebar       = dynamic(() => import('./TourSidebar'));
const TourBottomActions = dynamic(() => import('./TourBottomActions'));
const TourDescription   = dynamic(() => import('./TourDescription'));
const TourProgram       = dynamic(() => import('./TourProgram'));
const TourGallery       = dynamic(() => import('./TourGallery'));
const TourEssentials    = dynamic(() => import('./TourEssentials'));
const TourDates         = dynamic(() => import('./TourDates'));
const TourFAQ           = dynamic(() => import('./TourFAQ'));
const TourActionButtons = dynamic(() => import('./TourActionButtons'));
const SimilarTours      = dynamic(() => import('./SimilarTours'));

interface TourDetailsWrapperProps {
  tour: Tour; // Основной тур остается полным (он нужен для страницы)
  similarTours: TourPreview[]; // ✅ ИЗМЕНЕНО: Похожие туры теперь легкие
  isWished: boolean;
}

// ✅ ДОБАВИЛИ: достаем isWished (по умолчанию false)
export default function TourDetailsWrapper({ tour, similarTours, isWished = false }: TourDetailsWrapperProps) {
  
  return (
    // overflow-x-hidden убран с корня — sticky сайдбар его не переживает
    <div className="bg-slate-950 min-h-screen pb-0 selection:bg-teal-500/30 selection:text-teal-200">

      <TourStickyNav />
      {/* ✅ ДОБАВИЛИ: Передаем пропс isWished дальше в TourHero */}
      <TourHero tour={tour} isWished={isWished} /> 

      <main className="container mx-auto px-4 relative z-10 mt-6 md:mt-10 pb-24">
        <div className="grid lg:grid-cols-12 gap-8 items-start">

          {/* Левая колонка: overflow-x-hidden только здесь, не на родителе */}
          <div className="lg:col-span-8 flex flex-col gap-8 md:gap-10 overflow-x-hidden">
            <TourStats tour={tour} />
            <TourLogistics tour={tour} />
            <TourDescription tour={tour} />
            <TourProgram program={tour.program} />
            <TourGallery images={tour.gallery || []} />
            <TourEssentials
              included={tour.included || []}
              additionalExpenses={tour.additionalExpenses || []}
              documents={tour.documents}
              checklist={tour.checklist}
              includedDetailed={tour.includedDetailed}
              excludedDetailed={tour.excludedDetailed}
            />
            <TourDates tour={tour} />
                <TourFAQ tour={tour} />
            <TourDirectionBanner categorySlug={tour.category?.slug ?? null} />
            <TourLegalLinks />
            <TourActionButtons tour={tour} />
          </div>

          {/* Правая колонка: self-start и relative убраны — они мешали sticky */}
          <div className="hidden lg:block lg:col-span-4">
            <div className="sticky top-24">
              <TourSidebar tour={tour} />
            </div>
          </div>

        </div>
        <SimilarTours tours={similarTours || []} />
      </main>

      <TourBottomActions tour={tour} />

    </div>
  );
}

"use client";

import React, { useState, useEffect } from 'react';
import Image from 'next/image';
import { Camera, X, ChevronLeft, ChevronRight, Maximize2 } from 'lucide-react';
import { clsx } from 'clsx';

interface TourGalleryProps {
  images?: string[];
}

export default function TourGallery({ images = [] }: TourGalleryProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [currentIndex, setCurrentIndex] = useState(0);

  if (!images || images.length === 0) return null;

  const displayedImages = images.slice(0, 5);
  const remainingCount = images.length - 5;

  const openLightbox = (index: number) => {
    setCurrentIndex(index);
    setIsOpen(true);
    document.body.style.overflow = 'hidden';
  };

  const closeLightbox = () => {
    setIsOpen(false);
    document.body.style.overflow = 'auto';
  };

  const nextImage = (e?: React.MouseEvent) => {
    e?.stopPropagation();
    setCurrentIndex((prev) => (prev + 1) % images.length);
  };

  const prevImage = (e?: React.MouseEvent) => {
    e?.stopPropagation();
    setCurrentIndex((prev) => (prev - 1 + images.length) % images.length);
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!isOpen) return;
      if (e.key === 'Escape') closeLightbox();
      if (e.key === 'ArrowRight') nextImage();
      if (e.key === 'ArrowLeft') prevImage();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen]);

  const mobileRowsClass = 
    displayedImages.length <= 1 ? 'grid-rows-1' :
    displayedImages.length <= 3 ? 'grid-rows-3' : 
    'grid-rows-4';

  return (
    <section className="scroll-mt-24 animate-in fade-in duration-500" id="gallery">
      
      <div className="flex items-center gap-4 mb-6 md:mb-8">
        <div className="w-10 h-10 bg-teal-500/10 rounded-xl flex items-center justify-center text-teal-500 border border-teal-500/20 shrink-0">
           <Camera size={20} />
        </div>
        <h2 className="text-2xl md:text-3xl font-black text-white uppercase">
           Галерея
        </h2>
      </div>

      {/* ✅ УМНАЯ СЕТКА: Используем aspect-ratio вместо жестких пикселей */}
      <div className={clsx(
        "grid grid-cols-2 md:grid-cols-4 gap-2 md:gap-4 rounded-[2rem] md:rounded-3xl overflow-hidden bg-slate-900 border border-white/5 shadow-xl",
        "md:grid-rows-2",
        mobileRowsClass,
        "aspect-[3/4] sm:aspect-[4/3] md:aspect-[2/1] lg:aspect-[2.5/1]"
      )}>
        
        {displayedImages.map((img, index) => {
          const isMain = index === 0;
          const isLastVisible = index === 4;

          return (
            <div 
              key={index}
              onClick={() => openLightbox(index)}
              className={clsx(
                "relative group cursor-pointer overflow-hidden bg-slate-800",
                isMain ? "col-span-2 row-span-2 md:col-span-2 md:row-span-2" : "col-span-1 row-span-1"
              )}
            >
              <Image 
                src={img} 
                alt={`Галерея тура фото ${index + 1}`} 
                fill 
                // ✅ ФОКУС: object-[center_20%] держит фокус на лицах (верхняя часть) при любой обрезке
                className="object-cover object-[center_20%] transition-transform duration-700 group-hover:scale-105"
               loading={isMain ? "eager" : "lazy"}
fetchPriority={isMain ? "low" : "auto"}
                sizes={
                  isMain 
                    ? "(max-width: 768px) 100vw, (max-width: 1280px) 50vw, 640px" 
                    : "(max-width: 768px) 50vw, (max-width: 1280px) 25vw, 320px"
                }
                quality={isMain ? 65 : 55}
              />
              
              {isLastVisible && remainingCount > 0 ? (
                 <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center border border-white/10 transition-colors group-hover:bg-slate-900/80">
                     <span className="text-2xl md:text-3xl font-black text-white">+{remainingCount}</span>
                 </div>
              ) : (
                 <div className="absolute inset-0 bg-black/0 group-hover:bg-black/20 transition-colors flex items-center justify-center opacity-0 group-hover:opacity-100">
                    <Maximize2 className="text-white drop-shadow-md" size={isMain ? 48 : 24} />
                 </div>
              )}
            </div>
          );
        })}
      </div>

      {/* ✅ ЛАЙТБОКС: Полностью переработан UX для мобильных и десктопов */}
      {isOpen && (
        <div 
          className="fixed inset-0 z-[9999] bg-black/98 isolate backdrop-blur-xl flex flex-col items-center justify-center touch-none animate-in fade-in duration-200"
          onClick={closeLightbox}
        >
          {/* КОНТЕЙНЕР КАРТИНКИ: Используем динамическую высоту dvh */}
          <div 
             key={currentIndex}
             className="relative w-full h-[85dvh] md:h-[90dvh] max-w-7xl mx-auto flex items-center justify-center animate-in zoom-in-95 duration-200"
             onClick={(e) => e.stopPropagation()}
          >
             <Image 
               src={images[currentIndex]} 
               alt={`Фотография ${currentIndex + 1} из ${images.length}`} 
               fill 
               className="object-contain" // Картинка впишется без черных полос и обрезки
               priority
               sizes="100vw"
               quality={75}
             />
          </div>

          {/* СТРЕЛКИ НАВИГАЦИИ (Только если фото больше 1) */}
          {images.length > 1 && (
            <>
              <button 
                className="absolute left-2 md:left-6 top-1/2 -translate-y-1/2 p-3 md:p-4 bg-black/40 md:bg-transparent rounded-full text-white/70 hover:text-white transition-colors hover:scale-110 active:scale-95 z-[10000]"
                aria-label="Предыдущее фото" 
                onClick={prevImage}
              >
                 <ChevronLeft size={36} className="md:w-12 md:h-12" />
              </button>
              <button 
                className="absolute right-2 md:right-6 top-1/2 -translate-y-1/2 p-3 md:p-4 bg-black/40 md:bg-transparent rounded-full text-white/70 hover:text-white transition-colors hover:scale-110 active:scale-95 z-[10000]"
                aria-label="Следующее фото" 
                onClick={nextImage}
              >
                 <ChevronRight size={36} className="md:w-12 md:h-12" />
              </button>
            </>
          )}

          {/* СЧЕТЧИК ФОТО (Перемещен выше кнопки закрытия) */}
          <div className="absolute bottom-[max(6rem,calc(env(safe-area-inset-bottom)+4.5rem))] left-1/2 -translate-x-1/2 px-5 py-2.5 bg-black/60 rounded-full text-white/90 font-bold text-sm backdrop-blur-md border border-white/10 shadow-lg z-[10000] pointer-events-none">
             {currentIndex + 1} / {images.length}
          </div>

          {/* КНОПКА ЗАКРЫТИЯ (В зоне большого пальца по центру) */}
          <button 
            className="absolute bottom-[max(2rem,env(safe-area-inset-bottom))] left-1/2 -translate-x-1/2 flex items-center gap-2 px-6 py-3 bg-white/10 hover:bg-white/20 active:bg-white/30 text-white backdrop-blur-md border border-white/10 rounded-full transition-all z-[10000] shadow-xl"
            aria-label="Закрыть галерею" 
            onClick={closeLightbox}
          >
             <X size={20} />
             <span className="text-sm font-medium">Закрыть</span>
          </button>

          {/* Зоны клика для навигации на мобильных (невидимые) */}
          <div className="absolute inset-y-0 left-0 w-1/3 z-40 md:hidden" onClick={(e) => { e.stopPropagation(); prevImage(); }} />
          <div className="absolute inset-y-0 right-0 w-1/3 z-40 md:hidden" onClick={(e) => { e.stopPropagation(); nextImage(); }} />
        </div>
      )}

    </section>
  );
}

import React from 'react';
import Image from 'next/image';
import Link from 'next/link';
import { MapPin, Clock, Calendar, ArrowLeft, Tent } from 'lucide-react';
import { Tour } from '@/features/tours/types';
import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
import TourWishlistButton from './TourWishlistButton'; 

function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

const COLOR_THEMES: Record<string, string> = {
  slate:   "bg-slate-500 text-white",
  teal:    "bg-teal-500 text-slate-900",
  emerald: "bg-emerald-500 text-slate-900",
  sky:     "bg-sky-500 text-slate-900",
  blue:    "bg-blue-500 text-white",
  violet:  "bg-violet-500 text-white",
  pink:    "bg-pink-500 text-white",
  rose:    "bg-rose-500 text-white",
  orange:  "bg-orange-500 text-slate-900",
  amber:   "bg-amber-500 text-slate-900",
};

interface TourHeroProps {
  tour: Tour;
  isWished: boolean; // ✅ Добавили пропс
}

export default function TourHero({ tour, isWished }: TourHeroProps) {
  
  // ✅ ИСПРАВЛЕНА ЛОГИКА ДАТ: Теперь проверяются и дни, чтобы не было "26 - 26 апреля"
  const renderDateRange = () => {
    if (!tour.date) return 'Дата уточняется';
    
    const startDate = new Date(tour.date);
    const ruDate = new Intl.DateTimeFormat('ru-RU', { day: 'numeric', month: 'long' });
    const dayOnly = new Intl.DateTimeFormat('ru-RU', { day: 'numeric' });

    if (!tour.endDate) return ruDate.format(startDate);

    const endDate = new Date(tour.endDate);

    // 1. Если даты абсолютно одинаковые (тот же день, месяц и год) — выводим одну дату
    if (
      startDate.getDate() === endDate.getDate() &&
      startDate.getMonth() === endDate.getMonth() &&
      startDate.getFullYear() === endDate.getFullYear()
    ) {
      return ruDate.format(startDate);
    }

    // 2. Если дни разные, но месяц один — выводим "26 — 28 апреля"
    if (startDate.getMonth() === endDate.getMonth()) {
       return `${dayOnly.format(startDate)} — ${ruDate.format(endDate)}`;
    }
    
    // 3. Если месяцы разные — выводим "28 апреля — 2 мая"
    return `${ruDate.format(startDate)} — ${ruDate.format(endDate)}`;
  };

  const getDuration = () => {
    if (tour.duration) return tour.duration;
    if (tour.date && tour.endDate) {
      const start = new Date(tour.date).getTime();
      const end = new Date(tour.endDate).getTime();
      const days = Math.ceil((end - start) / (1000 * 60 * 60 * 24)) + 1;
      return `${days} дней`;
    }
    return '1 день';
  };

  const themeColor = tour.category?.color || 'teal';
  const badgeStyle = COLOR_THEMES[themeColor] || COLOR_THEMES.teal;
  const typeLabel = tour.category?.title || 'Тур';

  return (
    <section className="relative h-[80vh] min-h-[550px] w-full flex items-end overflow-hidden">
      
      <div className="absolute inset-0 z-0">
        <Image
          src={tour.image || '/placeholder-tour.jpg'}
          alt={tour.title || "Тур"}
          fill
          className="object-cover opacity-60"
          priority
          fetchPriority="high"
          quality={65} 
          sizes="100vw"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-slate-950/40 to-transparent" />
        <div className="absolute inset-x-0 top-0 h-32 bg-gradient-to-b from-slate-950/60 to-transparent" />
      </div>

   <div className="absolute top-24 left-4 md:left-8 z-20">
        <Link
          href="/tour"
          className="inline-flex items-center gap-2 px-4 py-2 bg-white/10 hover:bg-white/20 border border-white/10 backdrop-blur-md rounded-full text-slate-200 hover:text-white transition-all text-[11px] md:text-xs font-bold uppercase tracking-widest shadow-lg group"
        >
          <ArrowLeft size={16} className="group-hover:-translate-x-1 transition-transform" />
          В каталог
        </Link>
      </div>

      {/* ✅ ДОБАВЛЕНО: Кнопка добавления в избранное (выровнена симметрично кнопке "В каталог") */}
      <div className="absolute top-24 right-4 md:right-8 z-20">
        <TourWishlistButton tourId={tour.id} initialIsWished={isWished} />
      </div>

      <div className="container mx-auto px-4 relative z-10 pb-4 md:pb-8 pt-32 flex flex-col justify-end h-full">
        
        <div className="animate-in fade-in slide-in-from-bottom-4 duration-700 space-y-4 md:space-y-6 max-w-5xl mt-10">
            <div className="flex flex-wrap gap-2 md:gap-3">
              
              <span className={cn(
                "px-3 py-1 rounded-md text-[14px] md:text-xs font-black uppercase tracking-widest backdrop-blur-md",
                badgeStyle
              )}>
                  {typeLabel}
              </span>

              {tour.label && (
                <span className="px-3 py-1 rounded-md bg-white/20 text-white border border-white/20 text-[14px] md:text-xs font-bold uppercase tracking-widest backdrop-blur-md">
                    {tour.label}
                </span>
              )}
            </div>

            <h1 className="text-3xl md:text-5xl lg:text-6xl font-black text-white uppercase leading-[1.1] tracking-tight drop-shadow-xl break-words">
              {tour.title}
            </h1>
            
            {tour.subtitle && (
              <p className="text-sm md:text-lg text-slate-200 font-normal max-w-2xl leading-relaxed opacity-90 break-words">
                {tour.subtitle}
              </p>
            )}

            <div className="pt-6 md:pt-8 mt-4 border-t border-white/10">
                {/* ✅ ИСПРАВЛЕНА СЕТКА: Теперь это grid-cols-2 на мобилке без разрывов */}
                <div className="grid grid-cols-2 md:flex md:items-center gap-y-6 gap-x-8 md:gap-10 text-white">
                    
                    <div className="flex items-center gap-3 min-w-0">
                        <div className="w-8 h-8 rounded-full bg-white/10 flex items-center justify-center text-teal-400 shrink-0">
                            <MapPin size={16} />
                        </div>
                        <div className="min-w-0 flex-1">
                            <p className="text-[12px] uppercase text-slate-300 font-bold tracking-widest mb-0.5 truncate" title="Локация">Локация</p>
                            <p className="font-bold text-sm md:text-base leading-none truncate" title={tour.location}>{tour.location}</p>
                        </div>
                    </div>

                    <div className="flex items-center gap-3 min-w-0">
                        <div className="w-8 h-8 rounded-full bg-white/10 flex items-center justify-center text-teal-400 shrink-0">
                            <Calendar size={16} />
                        </div>
                        <div className="min-w-0 flex-1">
                            <p className="text-[12px] uppercase text-slate-300 font-bold tracking-widest mb-0.5 truncate" title="Даты">Даты</p>
                            <p className="font-bold text-sm md:text-base leading-none capitalize truncate" title={renderDateRange()}>{renderDateRange()}</p>
                        </div>
                    </div>

                    {/* ✅ ИСПРАВЛЕНО: Убран col-span-2, чтобы вставало в идеальный квадрат 2x2 на мобилках */}
                    <div className="flex items-center gap-3 min-w-0">
                        <div className="w-8 h-8 rounded-full bg-white/10 flex items-center justify-center text-teal-400 shrink-0">
                            <Clock size={16} />
                        </div>
                        <div className="min-w-0 flex-1">
                            <p className="text-[12px] uppercase text-slate-300 font-bold tracking-widest mb-0.5 truncate" title="Длительность">Длительность</p>
                            <p className="font-bold text-sm md:text-base leading-none truncate" title={getDuration()}>{getDuration()}</p>
                        </div>
                    </div>

                    {/* ✅ ДОБАВЛЕНО: Четвертая метрика "Проживание" */}
                    <div className="flex items-center gap-3 min-w-0">
                        <div className="w-8 h-8 rounded-full bg-white/10 flex items-center justify-center text-teal-400 shrink-0">
                            <Tent size={16} />
                        </div>
                        <div className="min-w-0 flex-1">
                            <p className="text-[12px] uppercase text-slate-300 font-bold tracking-widest mb-0.5 truncate" title="Проживание">Проживание</p>
                            <p className="font-bold text-sm md:text-base leading-none truncate" title={tour.accommodation || 'Без проживания'}>
                              {tour.accommodation || 'Без проживания'}
                            </p>
                        </div>
                    </div>

                </div>
            </div>

        </div>
      </div>
    </section>
  );
}

