            </div>
            <div className="w-1 h-1 rounded-full bg-slate-700 shrink-0" />
            <div className="flex items-center gap-1.5">
              <Clock size={12} className="text-teal-600" strokeWidth={2.5} />
              <span className="text-slate-300">{duration || '1 день'}</span>
