            <Backpack size={16} aria-hidden="true" /> Что взять с собой
          </h3>
          
          {Array.isArray(checklist) && checklist.length > 0 ? (
            <div className="space-y-6">
              {checklist.map((block: any, idx: number) => (
                <div key={idx}>
                  <h4 className="text-white font-bold text-sm mb-2 uppercase tracking-wide">
                    {block.title || `Категория ${idx + 1}`}
                  </h4>
                  <div className="text-slate-300 text-sm leading-relaxed whitespace-pre-line pl-2 border-l-2 border-teal-500/30">
                    {block.items}
                  </div>
                </div>
              ))}
            </div>
          ) : typeof checklist === 'string' && checklist.trim() !== '' ? (
            <div className="text-slate-300 text-sm leading-relaxed whitespace-pre-line">
              {checklist}
            </div>
          ) : (
            <p className="text-slate-300 text-sm italic">
              Специальное снаряжение не требуется. Достаточно удобной одежды по погоде.
            </p>
          )}
        </div>

        {/* БЛОК ДОКУМЕНТОВ */}
        <div className="bg-slate-900/40 border border-white/5 rounded-2xl p-6">
          <h3 className="text-teal-400 font-black uppercase tracking-widest text-[13px] flex items-center gap-2 mb-6 border-b border-white/5 pb-4">
            <ShieldCheck size={16} aria-hidden="true" /> Документы
          </h3>
          
          {Array.isArray(documents) && documents.length > 0 ? (
            <div className="space-y-3">
              {documents.map((doc: any, i: number) => (
                <Link 
                  key={i} 
                  href={doc.url || '#'} 
                  target="_blank"
                  className="group flex items-center justify-between p-3 bg-white/5 hover:bg-teal-500/10 border border-white/5 hover:border-teal-500/30 rounded-xl transition-all"
                >
                  <div className="flex items-center gap-3 overflow-hidden">
                    <div className="w-8 h-8 rounded-lg bg-slate-800 flex items-center justify-center text-slate-300 group-hover:text-teal-400 transition-colors shrink-0">
                      <FileText size={16} aria-hidden="true" />
                    </div>
                    <div className="flex flex-col overflow-hidden">
                      <span className="text-[12px] font-bold text-slate-300 uppercase tracking-widest">Файл</span>
                      <span className="text-sm font-bold text-slate-200 truncate group-hover:text-white transition-colors">
                        {doc.title || `Документ ${i + 1}`}
                      </span>
                    </div>
                  </div>
                  <Download size={16} className="text-slate-600 group-hover:text-teal-500 transition-colors shrink-0" aria-hidden="true" />
                </Link>
              ))}
            </div>
          ) : (
            <p className="text-slate-300 text-sm italic">
              Для этого тура специальные документы не требуются.
            </p>
          )}
        </div>
        
      </div>
    </section>
  );
}

files.src/features/tours/components/ToursBrows:
"use client";

import React, { useState, useMemo, useEffect, Suspense } from 'react';
import { useSearchParams } from 'next/navigation';
import { 
  LayoutGrid, Calendar as CalendarIcon, 
  Flame, Sparkles, Layers, Filter, X, Bell, ArrowRight,
  Compass, Map as MapIcon, Sun, Snowflake, TreePine, Bike, Footprints, MapPin, Anchor, Star, Waves,
  TrendingUp, ArrowDownCircle, Mountain, Tent, Droplets, Baby // ✅ ВСЕ ИКОНКИ НА МЕСТЕ
} from 'lucide-react';
import Link from 'next/link';
import { TourPreview, TourDateItem } from '@/features/tours/types';
import dynamic from 'next/dynamic';
import TourCard from './TourCard';
import { useModalStore } from '@/shared/store/useModalStore'; 
import { cn } from '@/lib/utils';

const CalendarView = dynamic(() => import('./CalendarView'), {
  ssr: true,
  loading: () => (
    <div className="h-[300px] w-full bg-slate-800/30 animate-pulse rounded-[1.5rem] border border-white/5 mt-4" />
  ),
});

// ✅ ИСПРАВЛЕНО: Честный маппинг всех иконок без костылей
const getIconComponent = (iconName: string, size = 14) => {
  const icons: Record<string, any> = {
    Compass, Tent, Mountain, Waves, Map: MapIcon, Sun, Snowflake,
    TreePine, Bike, Footprints, MapPin, Anchor, Flame, Star, Droplets, Baby
  };
  const IconComponent = icons[iconName] || Layers; 
  return <IconComponent size={size} />;
};

interface ToursBrowserProps {
  tours: TourPreview[];
  categories?: any[]; 
  title?: string;
  subtitle?: string;
  limit?: number;
  }

// Слушатель для начальной инициализации фильтра из URL
function ParamsListener({ onChange }: { onChange: (val: string) => void }) {
  const searchParams = useSearchParams();
  
  useEffect(() => {
    // Устанавливаем категорию только при маунте, чтобы не было конфликтов
    const cat = searchParams.get('category');
    if (cat) onChange(cat);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []); 
  
  return null;
}

export default function ToursBrowser({ 
    tours = [], 
    categories = [], 
    title = "Афиша Приключений", 
    subtitle = "ТУРЫ КЛУБА",
    limit = 8, // По умолчанию показываем 8, остальные по кнопке "Показать еще"
   }: ToursBrowserProps) {
  
  const openContactModal = useModalStore((state) => state.openContactModal);
  
  // ✅ ИСПРАВЛЕНО: Мгновенный стейт вместо зависимости от роутера Next.js
  const [activeCategory, setActiveCategory] = useState<string>('all');
  const [viewMode, setViewMode] = useState<'grid' | 'calendar'>('grid');
  const [isMobileFiltersOpen, setIsMobileFiltersOpen] = useState(false);
  const [visibleCount, setVisibleCount] = useState(limit); // Для пагинации

  const displayCategories = useMemo(() => {
    const allBtn = { id: 'all', slug: 'all', label: 'Все', icon: <Layers size={14}/> };
    const dbCats = categories.filter(c => c.isActive !== false).map(c => ({
       id: c.id,
       slug: c.slug,
       label: c.title,
       icon: getIconComponent(c.icon)
    }));
    return [allBtn, ...dbCats];
  }, [categories]);
  
  const handleCategoryClick = (slug: string) => {
    // 1. Мгновенно обновляем стейт (нулевая задержка UI)
    setActiveCategory(slug);
    setVisibleCount(limit); // Сбрасываем пагинацию при смене категории
    setIsMobileFiltersOpen(false);

    // 2. Тихо обновляем URL без перезагрузки страницы и запросов на сервер
    const url = new URL(window.location.href);
    if (slug === 'all') {
      url.searchParams.delete('category'); 
    } else {
      url.searchParams.set('category', slug); 
    }
    window.history.replaceState(null, '', url.toString());
  };

  // --- SMART FEED LOGIC (Новая логика: Строгая хронология + Анонсы) ---
  const { scheduledTours, tbaTours, allFilteredTours } = useMemo(() => {
    const safeTours = tours || [];
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    
    // 1. Фильтрация категорий и прошедших туров
    const filtered = safeTours.filter(tour => {
      // Категория
      if (activeCategory !== 'all') {
        const tourCategorySlug = tour.category?.slug;
        if (tourCategorySlug !== activeCategory.toLowerCase()) return false;
      }

      // Отсекаем полностью прошедшие
      if (tour.dates && tour.dates.length > 0) {
        const hasFutureDate = tour.dates.some((d: any) => {
           const dateToCompare = d.end ? new Date(d.end) : new Date(d.start);
           dateToCompare.setHours(0, 0, 0, 0);
           return dateToCompare >= today;
        });
        if (!hasFutureDate) return false;
      } else if (tour.date) {
        const singleDate = new Date(tour.date);
        singleDate.setHours(0, 0, 0, 0);
        if (singleDate < today) return false;
      }
      
      return true;
    });

    // 2. Хронологическая сортировка
    const sorted = filtered.sort((a, b) => {
        const dateA = a.date ? new Date(a.date).getTime() : Infinity;
        const dateB = b.date ? new Date(b.date).getTime() : Infinity;
        return dateA - dateB;
    });

    // 3. Разделение на "С датами" (scheduled) и "Без дат / Анонсы" (tba)
    const scheduled: TourPreview[] = []; // ✅ ИЗМЕНЕНО: TourPreview
    const tba: TourPreview[] = []; // ✅ ИЗМЕНЕНО: TourPreview

    sorted.forEach(t => {
        // Если у тура нет даты или пустой массив дат — это анонс
        if (!t.date || (t.dates && t.dates.length === 0)) {
            tba.push(t);
        } else {
            scheduled.push(t);
        }
    });

    return { scheduledTours: scheduled, tbaTours: tba, allFilteredTours: sorted };
  }, [tours, activeCategory]);

  const displayScheduled = scheduledTours.slice(0, visibleCount);
  const hasMoreScheduled = visibleCount < scheduledTours.length;

  return (
    <section className="py-8 md:py-24 bg-slate-950 min-h-screen relative overflow-hidden" id="tours">
      
      <Suspense fallback={null}>
        <ParamsListener onChange={setActiveCategory} />
      </Suspense>

      <div className="absolute top-0 right-0 w-[800px] h-[600px] bg-teal-900/5 md:blur-[120px] rounded-full pointer-events-none opacity-60" />

      <div className="container mx-auto px-4 max-w-7xl relative z-10">
        
        {/* --- HEADER --- */}
        <div className="mb-8 md:mb-14">
            <div className="flex flex-wrap items-center gap-3 mb-4">
                <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full border border-teal-500/20 bg-teal-950/30 backdrop-blur-md">
                   <CalendarIcon size={14} className="text-teal-400" />
                  <span className="text-[16px] font-bold uppercase tracking-widest text-teal-400">{subtitle}</span>
                </div>
               </div>
            
            <h1 className="text-4xl md:text-6xl lg:text-7xl uppercase tracking-tighter leading-[0.9] text-white font-black">
                {title}
            </h1>
        </div>

        {/* =======================================================
           MOBILE CONTROLS 
           ======================================================= */}
        <div className="lg:hidden mb-8 sticky top-4 z-40">
            <div className="grid grid-cols-3 gap-2 p-1 bg-slate-900/90 backdrop-blur-xl border border-white/10 rounded-full shadow-2xl">
                
                <button 
                    onClick={() => { setViewMode('grid'); setIsMobileFiltersOpen(false); }}
                    className={cn(
                        "flex items-center justify-center gap-1.5 py-2.5 rounded-full transition-all",
                        viewMode === 'grid' ? "bg-teal-500 text-slate-900 shadow-md" : "bg-transparent text-slate-300 active:bg-white/10"
                    )}
                >
                    <LayoutGrid size={15} strokeWidth={2.5} />
                    <span className="text-[12px] font-bold uppercase tracking-wider mt-0.5">Сетка</span>
                </button>

                <button 
                    onClick={() => { setViewMode('calendar'); setIsMobileFiltersOpen(false); }}
                    className={cn(
                        "flex items-center justify-center gap-1.5 py-2.5 rounded-full transition-all",
                        viewMode === 'calendar' ? "bg-teal-500 text-slate-900 shadow-md" : "bg-transparent text-slate-300 active:bg-white/10"
                    )}
                >
                    <CalendarIcon size={15} strokeWidth={2.5} />
                    <span className="text-[12px] font-bold uppercase tracking-wider mt-0.5">Календарь</span>
                </button>

                <button 
                    onClick={() => setIsMobileFiltersOpen(!isMobileFiltersOpen)}
                    className={cn(
                        "flex items-center justify-center gap-1.5 py-2.5 rounded-full transition-all border",
                        isMobileFiltersOpen ? "bg-slate-800 text-white border-teal-500/50" : "bg-transparent border-transparent text-slate-300 active:bg-white/10"
                    )}
                >
                    {isMobileFiltersOpen ? <X size={15} strokeWidth={2.5}/> : <Filter size={15} strokeWidth={2.5} />}
                    <span className="text-[12px] font-bold uppercase tracking-wider mt-0.5">Фильтры</span>
                </button>
            </div>

            {isMobileFiltersOpen && (
                <div className="overflow-hidden mt-2 bg-slate-900/95 backdrop-blur-md rounded-2xl border border-white/10 animate-in fade-in slide-in-from-top-2 duration-200">
                    <div className="p-4">
                        <span className="text-[12px] font-bold text-slate-300 uppercase tracking-widest mb-3 block">Категории туров:</span>
                        <div className="flex flex-wrap gap-2">
                            {displayCategories.map(cat => (
                                <button
                                    key={cat.id}
                                    onClick={() => handleCategoryClick(cat.slug)}
                                    className={cn(
                                        "flex items-center gap-2 px-3 py-2 rounded-lg text-xs font-bold uppercase tracking-wider transition-all border",
                                        activeCategory === cat.slug
                                            ? "text-teal-900 bg-teal-500 border-teal-500" 
                                            : "text-slate-300 bg-white/5 border-white/5 hover:bg-white/10"
                                    )}
                                >
                                    {cat.icon} {cat.label}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            )}
        </div>

        {/* =======================================================
            DESKTOP CONTROLS
           ======================================================= */}
        <div className="hidden lg:block sticky top-4 z-40 mb-12">
            <div className="bg-slate-900/90 backdrop-blur-xl border border-white/10 rounded-2xl p-2 shadow-2xl flex flex-row items-center justify-between gap-4">
                
                <div className="bg-white/5 p-1 rounded-xl flex items-center shrink-0 h-full self-start">
                    <button 
                        onClick={() => setViewMode('grid')}
                        className={cn(
                            "flex items-center justify-center gap-2 px-5 py-2.5 rounded-lg text-xs font-bold uppercase transition-all h-full",
                            viewMode === 'grid' ? "bg-teal-500 text-slate-900 shadow-lg" : "text-slate-300 hover:text-white"
                        )}
                    >
                        <LayoutGrid size={16}/> <span>Сетка</span>
                    </button>
                    <button 
                        onClick={() => setViewMode('calendar')}
                        className={cn(
                            "flex items-center justify-center gap-2 px-5 py-2.5 rounded-lg text-xs font-bold uppercase transition-all h-full",
                            viewMode === 'calendar' ? "bg-teal-500 text-slate-900 shadow-lg" : "text-slate-300 hover:text-white"
                        )}
                    >
                        <CalendarIcon size={16}/> <span>Календарь</span>
                    </button>
                </div>

                <div className="w-px h-8 bg-white/10 shrink-0 self-center" />

                <div className="flex-1 flex flex-wrap items-center justify-start gap-2 py-1">
                    {displayCategories.map(cat => (
                        <button
                            key={cat.id}
                            onClick={() => handleCategoryClick(cat.slug)}
                            className={cn(
                                "flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-bold uppercase tracking-wider transition-all border border-transparent",
                                activeCategory === cat.slug
                                    ? "text-teal-400 bg-teal-500/10 border-teal-500/20" 
                                    : "text-slate-300 hover:text-white hover:bg-white/5"
                            )}
                        >
                            {cat.icon} {cat.label}
                        </button>
                    ))}
                </div>

                <div className="w-px h-8 bg-white/10 shrink-0 self-center" />

                <Link 
                    href="/tour" 
                    className="flex items-center justify-center gap-2 px-6 py-3 rounded-xl bg-white/10 hover:bg-teal-500 hover:text-slate-900 border border-white/10 text-white text-xs font-bold uppercase tracking-widest transition-all group shrink-0 h-full self-start"
                >
                    <span>Все туры</span>
                    <ArrowRight size={14} className="group-hover:translate-x-1 transition-transform"/>
                </Link>
            </div>
        </div>

        {/* =======================================================
            CONTENT RENDERER
           ======================================================= */}
        
        {viewMode === 'calendar' ? (
             <div className="animate-in fade-in zoom-in duration-300">
                <CalendarView events={allFilteredTours} />
             </div>
        ) : (
            <div className="space-y-12 md:space-y-16 animate-in fade-in slide-in-from-bottom-4 duration-500">
                
                {/* 1. БЛИЖАЙШИЕ ТУРЫ (Сетка + Свайп на мобилке) */}
                {scheduledTours.length > 0 && (
                    <section aria-labelledby="scheduled-tours-heading">
                        <div className="flex items-center gap-4 mb-6 md:mb-8 border-b border-white/5 pb-4">
                            <Flame size={18} className="text-amber-500 animate-pulse" />
                            <h3 id="scheduled-tours-heading" className="text-sm md:text-base font-bold uppercase tracking-[0.15em] text-amber-500">
                                Расписание
                            </h3>
                        </div>

                        {/* ✅ УНИФИЦИРОВАННАЯ СЕТКА: Свайп на мобилках, 2-3-4 колонки на больших экранах */}
                        <div className="relative">
                            <div className="flex overflow-x-auto snap-x snap-mandatory gap-4 pb-8 -mx-4 px-4 md:grid md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 md:gap-6 md:overflow-visible md:pb-0 md:mx-0 md:px-0 [&::-webkit-scrollbar]:hidden [-ms-overflow-style:none] [scrollbar-width:none]">
                                {displayScheduled.map((tour, index) => (
                                    <div key={tour.id} className="snap-center shrink-0 w-[85vw] md:w-auto h-full">
                                        <TourCard tour={tour} isHot priority={index < 4} />
                                    </div>
                                ))}
                            </div>
                            
                            {/* Подсказка для свайпа на мобилках */}
                            <div className="flex md:hidden items-center justify-end gap-1.5 mt-2 pr-4 text-slate-300 pointer-events-none">
                                <span className="text-[12px] font-bold uppercase tracking-widest">Листай вбок</span>
                                <ArrowRight size={14} className="text-teal-500 animate-pulse" />
                            </div>
                        </div>

                        {/* Кнопка "Показать еще" */}
                        {hasMoreScheduled && (
                            <div className="flex justify-center mt-10">
                                <button
                                    onClick={() => setVisibleCount(prev => prev + limit)}
                                    className="group flex items-center gap-3 px-8 py-4 bg-white/5 hover:bg-white/10 border border-white/10 text-white font-bold rounded-2xl transition-all shadow-lg hover:shadow-teal-500/10 hover:border-teal-500/30"
                                >
                                    <span className="uppercase tracking-wider text-sm">Показать еще туры</span>
                                    <ArrowDownCircle size={20} className="text-teal-400 group-hover:translate-y-1 transition-transform" />
                                </button>
                            </div>
                        )}
                    </section>
                )}

                {/* 2. АНОНСЫ (Туры без дат) */}
                {tbaTours.length > 0 && (
                    <section aria-labelledby="soon-tours-heading">
                        <div className="flex items-center gap-4 mb-6 md:mb-8 border-b border-white/5 pb-4">
                            <Sparkles size={18} className="text-slate-300" />
                            <h3 id="soon-tours-heading" className="text-sm md:text-base font-bold uppercase tracking-[0.15em] text-slate-300">
                                Планируй заранее (Анонсы)
                            </h3>
                        </div>

                        {/* ✅ УНИФИЦИРОВАННАЯ СЕТКА АНОНСОВ */}
                        <div className="relative">
                            <div className="flex overflow-x-auto snap-x snap-mandatory gap-4 pb-8 -mx-4 px-4 md:grid md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 md:gap-6 md:overflow-visible md:pb-0 md:mx-0 md:px-0 [&::-webkit-scrollbar]:hidden [-ms-overflow-style:none] [scrollbar-width:none]">
                                {tbaTours.map((tour) => (
                                    <div key={tour.id} className="snap-center shrink-0 w-[85vw] md:w-auto h-full opacity-90 hover:opacity-100 transition-opacity">
                                        <TourCard tour={tour} />
                                    </div>
                                ))}
                            </div>
                            
                            <div className="flex md:hidden items-center justify-end gap-1.5 mt-2 pr-4 text-slate-300 pointer-events-none">
                                <span className="text-[12px] font-bold uppercase tracking-widest">Листай вбок</span>
                                <ArrowRight size={14} className="text-teal-500 animate-pulse" />
                            </div>
                        </div>
                    </section>
                )}

                {/* 3. ПУСТОЕ СОСТОЯНИЕ */}
                {scheduledTours.length === 0 && tbaTours.length === 0 && (
                    <div className="text-center py-12 md:py-24 px-4 border border-dashed border-white/10 rounded-[2rem] md:rounded-[3rem] bg-gradient-to-b from-white/[0.02] to-transparent relative overflow-hidden shadow-2xl">
                        <div className="absolute inset-0 bg-teal-500/5 md:blur-[100px] rounded-full" />
                        
                        <div className="relative z-10">
                            <div className="w-16 h-16 bg-slate-900 border border-white/5 rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-xl">
                                <Sparkles size={28} className="text-teal-500" />
                            </div>
                            
                            <h3 className="text-2xl md:text-3xl font-black text-white uppercase tracking-tight mb-3">
                                Расписание формируется
                            </h3>
                            <p className="text-sm md:text-base text-slate-300 font-medium mb-8 max-w-md mx-auto leading-relaxed">
                                Мы готовим новые даты в эту категорию. Хотите узнать о них первыми или заказать индивидуальный корпоративный сплав?
                            </p>
                            
                            <button 
                               onClick={() => openContactModal('TOUR', `Запрос уведомления о новых турах (Категория: ${activeCategory})`)}
                                className="inline-flex items-center justify-center gap-2 px-8 py-4 bg-white text-slate-950 font-black uppercase tracking-wider rounded-xl hover:bg-teal-50 hover:scale-105 transition-all shadow-[0_0_20px_rgba(255,255,255,0.2)] active:scale-95 w-full sm:w-auto"
                            >
                                <Bell size={18} />
                                <span>Уведомить о турах</span>
                            </button>
                        </div>
                    </div>
                )}
            </div>
        )}

      </div>
    </section>
  );
}

files.src/features/guides/components/GuidesEdi:
"use client";

import React from "react";
import Image from "next/image";
import Link from "next/link";
import { 
  Instagram, Send, ArrowRight, Zap, Flame, 
  Sparkles, Utensils, Activity, Heart, Compass, User 
} from "lucide-react";
import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
import { useModalStore } from '@/shared/store/useModalStore';	

function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

const ICON_MAP: Record<string, { icon: React.ElementType, color: string }> = {
  Zap: { icon: Zap, color: "text-amber-400" },
  Utensils: { icon: Utensils, color: "text-rose-400" },
  Sparkles: { icon: Sparkles, color: "text-purple-400" },
  Flame: { icon: Flame, color: "text-teal-400" },
  Activity: { icon: Activity, color: "text-sky-400" },
  Heart: { icon: Heart, color: "text-red-500" },
  Compass: { icon: Compass, color: "text-emerald-400" },
};

interface Guide {
  id: string;
  slug: string;
  name: string;
  role: string;
  image: string | null;       
  actionImage: string | null; 
  bio: string | null;
  fullBio: string | null;
  superpower: string | null;
  experience: string | null;
  tags: string[];
  achievements: string[];
  quotes: string[];
  stats: any; 
  instagram: string | null;
  telegram: string | null;
  order: number;
}

const SkillBar = ({ label, value, icon: Icon, colorClass }: any) => (
    <div className="mb-2">
       <div className="flex justify-between items-end mb-2">
          <div className="flex items-center gap-2 text-[12px] font-bold uppercase tracking-widest text-slate-300">
             <Icon size={14} className={colorClass} />
             <span>{label}</span>
          </div>
          <span className="text-xs font-mono font-bold text-white">{value}%</span>
       </div>
       <div className="h-1.5 w-full bg-white/5 rounded-full overflow-hidden">
          <div 
             style={{ width: `${value}%` }} 
             className={cn("h-full rounded-full shadow-[0_0_10px_currentColor] transition-all duration-1000 ease-out", colorClass.replace('text-', 'bg-'))}
          />
       </div>
    </div>
);

export default function GuidesEditorialList({ guides = [] }: { guides: Guide[] }) {
    const openContactModal = useModalStore((state) => state.openContactModal);
    
    const displayGuides = Array.isArray(guides) 
        ? [...guides].sort((a, b) => (a.order || 0) - (b.order || 0)) 
        : [];

    return (
        <div className="container mx-auto px-4 max-w-7xl">
            <div className="flex flex-col gap-24 md:gap-32 pb-24">
                
                {displayGuides.map((guide, index) => (
                    <EditorialGuideBlock 
                        key={guide.id} 
                        guide={guide} 
                        index={index} 
                        // FIX: priority только для первых 2, остальные lazy
                        priority={index < 2} 
                    />
                ))}

                <div className="relative mt-12 bg-slate-900/60 backdrop-blur-xl border border-white/5 rounded-[3rem] p-8 md:p-16 text-center overflow-hidden shadow-2xl animate-in fade-in slide-in-from-bottom-8 duration-700 fill-mode-both">
                    <div className="absolute top-0 left-1/2 -translate-x-1/2 w-full max-w-2xl h-[300px] bg-teal-500/10 blur-[100px] rounded-full pointer-events-none" />

                    <div className="relative z-10 flex flex-col items-center">
                        <div className="w-16 h-16 md:w-20 md:h-20 bg-teal-500/10 rounded-3xl flex items-center justify-center text-teal-400 mb-8 border border-teal-500/20 shadow-lg">
                            <Zap size={36} strokeWidth={1.5} />
                        </div>
                        <h2 className="text-3xl md:text-5xl lg:text-6xl font-black text-white uppercase tracking-tighter mb-4 leading-none">
                            Хочешь к нам  <br className="hidden md:block"/><span className="text-teal-500">в команду?</span>
                        </h2>
                        <p className="text-slate-300 font-medium text-base md:text-lg max-w-2xl leading-relaxed mb-10">
                            Мы всегда в поиске людей, влюбленных в природу: гидов, водителей, фотографов, поваров и технических помощников. 
                        </p>
                        <button
                            onClick={() => openContactModal(undefined, 'HR')}
                            className="w-full sm:w-auto px-10 py-5 bg-teal-500 hover:bg-teal-400 text-slate-950 font-black uppercase tracking-widest rounded-2xl transition-all shadow-[0_0_30px_rgba(20,184,166,0.3)] hover:shadow-[0_0_40px_rgba(20,184,166,0.5)] active:scale-95 flex items-center justify-center gap-3"
                        >
                            <span>Подать заявку</span>
                            <ArrowRight size={20} />
                        </button>
                    </div>
                </div>

            </div>
        </div>
    );
}

function EditorialGuideBlock({ guide, index, priority = false }: { guide: Guide, index: number, priority?: boolean }) {
    const isReverse = index % 2 !== 0;

    let parsedStats: any[] = [];
    if (guide.stats) {
        try { parsedStats = typeof guide.stats === 'string' ? JSON.parse(guide.stats) : guide.stats; } 
        catch (e) {}
    }

    return (
        <div
            className="grid grid-cols-1 lg:grid-cols-12 gap-10 lg:gap-16 items-center relative animate-in fade-in slide-in-from-bottom-8 duration-700 fill-mode-both"
            style={{ animationDelay: `${Math.min(index * 150, 600)}ms` }}
        >
            {/* КОЛОНКА 1: ФОТО */}
            <div className={cn(
                "lg:col-span-5 relative w-full aspect-[4/5] rounded-[2.5rem] overflow-hidden shadow-2xl border border-white/5 bg-slate-900 group",
                isReverse ? "lg:order-2" : "lg:order-1"
            )}>
                {guide.actionImage || guide.image ? (
                    <Image
                        src={guide.actionImage || guide.image || ''}
                        alt={guide.name}
                        fill
                        priority={priority}
                        // FIX: явный lazy для гидов 3+ чтобы не грузить всю страницу сразу
                        loading={priority ? undefined : "lazy"}
                        className="object-cover transition-transform duration-1000 group-hover:scale-105"
                        sizes="(max-width: 1024px) 100vw, 50vw"
                        // FIX: quality 65 — большие портреты, нужна детализация, но не максимум
                        quality={65}
                    />
                ) : (
                    <div className="w-full h-full flex items-center justify-center">
                        <User size={64} className="text-slate-700" />
                    </div>
                )}
                <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-slate-950/20 to-transparent opacity-60" />
            </div>

            {/* КОЛОНКА 2: ИНФОРМАЦИЯ */}
            <div className={cn(
                "lg:col-span-7 flex flex-col",
                isReverse ? "lg:order-1" : "lg:order-2"
            )}>
                <div className="flex flex-wrap items-center gap-3 mb-6">
                    <span className="px-4 py-1.5 bg-teal-500 text-slate-950 text-sm font-black uppercase tracking-widest rounded-lg shadow-lg">
                        {guide.role}
                    </span>
                    {guide.superpower && (
                        <span className="px-4 py-1.5 bg-slate-900 border border-white/10 text-slate-300 text-sm font-bold uppercase tracking-widest rounded-lg flex items-center gap-2 shadow-sm">
                            <Sparkles size={14} className="text-amber-400" /> {guide.superpower}
                        </span>
                    )}
                </div>

                <h2 className="text-5xl md:text-7xl font-black text-white uppercase tracking-tighter leading-none mb-6 drop-shadow-lg">
                    {guide.name}
                </h2>

                <div className="text-base md:text-lg text-slate-300 leading-relaxed mb-6 font-medium whitespace-pre-wrap">
                    {guide.bio || guide.fullBio}
                </div>

                <div className="flex flex-wrap gap-2 mb-8">
                    {guide.tags && guide.tags.map((tag, idx) => (
                        <span key={idx} className="px-3 py-1.5 bg-white/5 border border-white/10 text-slate-300 text-xs font-bold uppercase tracking-wider rounded-lg">
                            #{tag}
                        </span>
                    ))}
                </div>

                {parsedStats.length > 0 && (
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-8 gap-y-6 mb-8 p-6 md:p-8 bg-slate-900/50 rounded-3xl border border-white/5 shadow-inner">
                        {parsedStats.map((stat, i) => {
                            const mapping = ICON_MAP[stat.icon] || ICON_MAP['Zap'];
                            return (
                                <SkillBar
                                    key={i}
                                    label={stat.label}
                                    value={stat.value}
                                    icon={mapping.icon}
                                    colorClass={mapping.color}
                                />
                            );
                        })}
                    </div>
                )}

                <div className="flex flex-wrap items-center gap-4 mt-auto pt-8 border-t border-white/10">
                    <Link
                        href={`/guides/${guide.slug}`}
                        className="px-8 py-4 rounded-xl bg-white/10 hover:bg-white/20 text-white font-bold uppercase tracking-widest text-sm transition-all border border-white/5 hover:border-white/20 flex items-center gap-2 group w-full sm:w-auto justify-center"
                    >
                        Подробное досье
                        <ArrowRight size={16} className="group-hover:translate-x-1 transition-transform" />
                    </Link>
                    
                    {(guide.instagram || guide.telegram) && (
                        <div className="flex gap-3 justify-center w-full sm:w-auto">
                            {guide.instagram && (
                                <a href={guide.instagram} target="_blank" rel="noreferrer" className="w-12 h-12 flex items-center justify-center rounded-xl bg-slate-900 border border-white/10 hover:border-teal-500/50 text-slate-300 hover:text-teal-400 transition-all shadow-sm">
                                    <Instagram size={20} />
                                </a>
                            )}
                            {guide.telegram && (
                                <a href={guide.telegram} target="_blank" rel="noreferrer" className="w-12 h-12 flex items-center justify-center rounded-xl bg-slate-900 border border-white/10 hover:border-teal-500/50 text-slate-300 hover:text-teal-400 transition-all shadow-sm">
                                    <Send size={20} className="ml-[-2px]" />
                                </a>
                            )}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

