            ))}
          </div>
        </section>
      )}

      <section className="space-y-6 pt-4 border-t border-white/5 px-2 md:px-0">
        <h2 className="text-sm font-bold text-slate-300 uppercase tracking-wider">
          Предстоящие поездки
